// Cantrips and 1st-rank spells, verified against Archives of Nethys (queried
// via its Elasticsearch index — see PROJECT_NOTES.md). Scope note: this only
// includes spells with a `tradition` field in AoN's data — i.e. spells any
// caster of that tradition can freely pick — plus, as of v0.9.1, spells
// gated to one specific class (`classId`, see below) once that class's own
// sub-choice mechanic is understood well enough to model correctly. Spells
// gated behind a class sub-choice this app *doesn't* model well enough yet
// (Cleric Doctrine font cantrips — needs Deity; Witch Patron hexes — needs
// Familiars, since a Witch's cantrips come from "the spells your familiar
// knows," not the open tradition list) stay excluded — same simplification
// already used elsewhere (Cleric defaults to the Cloistered baseline).
//
// `traditions` uses lowercase codes: arcane, divine, occult, primal.
// `classId` (optional): set only on spells restricted to one class beyond
// the tradition filter — e.g. Bard Composition cantrips are Uncommon/
// Bard-trait spells any Bard has access to (regardless of which Muse),
// not spells every occult caster can pick. getSpellsForTradition() takes
// classId as a second filter so these only surface for that one class.
// `cast` is only set when the casting time isn't the default two actions.
// `desc` is the complete, unabridged rules text (not a summary) — this app
// is meant to be usable by brand-new players without a rulebook on hand, so
// nothing here is trimmed for card size. `heightened` (when present) holds
// the spell's Heightened entries verbatim, shown as its own block.

export const CANTRIPS = [
  { id: 'acid-splash', name: 'Acid Splash', traits: ['Acid', 'Attack', 'Cantrip', 'Evocation'], source: 'Core Rulebook pg. 316', range: '30 feet', target: '1 creature', traditions: ['arcane', 'primal'], desc: 'You splash a glob of acid that splatters your target and nearby creatures. Make a spell attack. If you hit, you deal 1d6 acid damage plus 1 splash acid damage. On a critical success, the target also takes 1 persistent acid damage.', heightened: 'Heightened (3rd) The initial damage increases to 2d6, and the persistent damage increases to 2. Heightened (5th) The initial damage increases to 3d6, the persistent damage increases to 3, and the splash damage increases to 2. Heightened (7th) The initial damage increases to 4d6, the persistent damage increases to 4, and the splash damage increases to 3. Heightened (9th) The initial damage increases to 5d6, the persistent damage increases to 5, and the splash damage increases to 4.', },
  { id: 'bullhorn', name: 'Bullhorn', traits: ['Auditory', 'Cantrip', 'Concentrate', 'Illusion', 'Manipulate'], source: 'Player Core 2 pg. 241', duration: '10 minutes', traditions: ['arcane', 'divine', 'occult'], desc: 'You amplify your voice, loud enough for you to be heard easily at a great distance. For the duration, your voice can be heard loudly and clearly by all listeners within 500 feet, even if other ambient noise would otherwise block the sound. Despite the volume, this doesn\'t make your voice jarring or distracting. This doesn\'t increase the range or area of other auditory or linguistic effects, and physical barriers such as walls and doors still block or muffle your voice as normal. Your loud voice makes it easier to Coerce others, and the acoustics assist in Performing at a large venue. You gain a +1 status bonus to checks to Coerce and auditory Performance checks to Perform at a large venue. You can Dismiss the spell.', heightened: 'Heightened (5th) Your voice can be heard clearly up to 1,200 feet away. Heightened (7th) Your voice can be heard clearly up to 1 mile away', },
  { id: 'caustic-blast', name: 'Caustic Blast', traits: ['Acid', 'Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 319', range: '30 feet', area: '5-foot burst', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'You fling a large glob of acid that immediately detonates, spraying nearby creatures. Creatures in the area take 1d8 acid damage with a basic Reflex save; on a critical failure, the creature also takes 1 persistent acid damage.', heightened: 'Heightened (+2) The initial damage increases by 1d8, and the persistent damage on a critical failure increases by 1.', },
  { id: 'chill-touch', name: 'Chill Touch', traits: ['Cantrip', 'Necromancy', 'Negative', 'Void'], source: 'Core Rulebook pg. 323', range: 'touch', target: '1 living or undead creature', defense: 'Fortitude', traditions: ['arcane', 'divine', 'occult'], desc: 'Siphoning negative energy into yourself, your hand radiates a pale darkness. Your touch weakens the living and disorients undead, possibly even causing them to flee. The effect depends on whether the target is living or undead. Living Creature The spell deals negative damage equal to 1d4 plus your spellcasting modifier. The target attempts a basic Fortitude save, but is also enfeebled 1 for 1 round on a critical failure. Undead Creature The target is off-guard for 1 round on a failed Fortitude save. On a critical failure, the target is also fleeing for 1 round unless it succeeds at a Will save.', heightened: 'Heightened (+1) The negative damage to living creatures increases by 1d4.', },
  { id: 'dancing-lights', name: 'Dancing Lights', traits: ['Cantrip', 'Evocation', 'Light'], source: 'Core Rulebook pg. 327', range: '120 feet', duration: 'sustained', traditions: ['arcane', 'occult', 'primal'], desc: 'You create up to four floating lights, no two of which are more than 10 feet apart. Each sheds light like a torch. When you Sustain the Spell, you can move any number of lights up to 60 feet. Each light must remain within 120 feet of you and within 10 feet of all others, or it winks out.', },
  { id: 'daze', name: 'Daze', traits: ['Cantrip', 'Concentrate', 'Manipulate', 'Mental', 'Nonlethal'], source: 'Player Core pg. 322', range: '60 feet', target: '1 creature', duration: '1 round', defense: 'Will', traditions: ['arcane', 'divine', 'occult'], desc: 'You push into the target\'s mind and daze it with a mental jolt. The jolt deals 1d6 mental damage, with a basic Will save. If the target critically fails the save, it is also stunned 1.', heightened: 'Heightened (+2) The damage increases by 1d6.', },
  { id: 'detect-magic', name: 'Detect Magic', traits: ['Cantrip', 'Concentrate', 'Detection', 'Manipulate'], source: 'Player Core pg. 323', area: '30-foot emanation', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'You send out a pulse that registers the presence of magic. You receive no information beyond the presence or absence of magic. You can choose to ignore magic you\'re fully aware of, such as the magic items and ongoing spells of you and your allies. You detect illusion magic only if that magic\'s effect has a lower rank than the rank of your detect magic spell. However, items that have an illusion aura but aren\'t deceptive in appearance (such as an invisibility potion) typically are detected normally.', heightened: 'Heightened (3rd) You learn the rank or level of the most powerful magical effect the spell detects, as determined by the GM. Heightened (4th) As 3rd rank, but you also pinpoint the source of the highest-rank magic. Like for an imprecise sense, you don\'t learn the exact location, but can narrow down the source to within a 5-foot cube (or the nearest if larger than that).', },
  { id: 'disrupt-undead', name: 'Disrupt Undead', traits: ['Cantrip', 'Necromancy', 'Positive', 'Vitality'], source: 'Core Rulebook pg. 331', range: '30 feet', target: '1 undead creature', defense: 'Fortitude', traditions: ['divine', 'primal'], desc: 'You lance the target with energy. You deal 2d6 vitality damage. The target must attempt a basic Fortitude save. If the creature critically fails the save, it is also enfeebled 1 for 1 round.', heightened: 'Heightened (+1) The damage increases by 1d6.', },
  { id: 'divine-lance', name: 'Divine Lance', traits: ['Attack', 'Cantrip', 'Concentrate', 'Manipulate', 'Sanctified', 'Spirit'], source: 'Player Core pg. 325', range: '60 feet', target: '1 creature', defense: 'AC', traditions: ['divine'], desc: 'You unleash a beam of divine energy. Make a ranged spell attack against the target\'s AC. On a hit, the target takes 2d4 spirit damage (double damage on a critical hit).', heightened: 'Heightened (+1) The damage increases by 1d4.', },
  { id: 'electric-arc', name: 'Electric Arc', traits: ['Cantrip', 'Concentrate', 'Electricity', 'Manipulate'], source: 'Player Core pg. 328', range: '30 feet', target: '1 or 2 creatures', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'An arc of lightning leaps from one target to another. Each target takes 2d4 electricity damage with a basic Reflex save.', heightened: 'Heightened (+1) The damage increases by 1d4.', },
  { id: 'figment', name: 'Figment', traits: ['Cantrip', 'Concentrate', 'Illusion', 'Manipulate', 'Subtle'], source: 'Player Core pg. 331', range: '30 feet', duration: 'sustained', traditions: ['arcane', 'occult'], desc: 'You create a simple illusory sound or vision. A sound adds the auditory trait to the spell and the sound can\'t include intelligible words or elaborate music. A vision adds the visual trait, can be no larger than a 5-foot cube, and is clearly crude and undetailed if viewed from within 15 feet. When you Cast or Sustain the Spell, you can attempt to Create a Diversion with the illusion, gaining a +2 circumstance bonus to your Deception check. If the attempt fails against a creature, that creature disbelieves the figment.', },
  { id: 'forbidding-ward', name: 'Forbidding Ward', traits: ['Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 332', range: '30 feet', target: '1 ally and 1 enemy', duration: 'sustained up to 1 minute', traditions: ['divine', 'occult'], desc: 'You ward an ally against the attacks and hostile spells from the target enemy. The target ally gains a +1 status bonus to Armor Class and saving throws against the target enemy\'s attacks, spells, and other effects.', heightened: 'Heightened (6th) The status bonus increases to +2.', },
  { id: 'frostbite', name: 'Frostbite', traits: ['Cantrip', 'Cold', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 332', range: '60 feet', target: '1 creature', defense: 'basic Fortitude', traditions: ['arcane', 'primal'], desc: 'An orb of biting cold coalesces around your target, freezing its body. The target takes 2d4 cold damage with a basic Fortitude save. On a critical failure, the target also gains weakness 1 to bludgeoning until the start of your next turn.', heightened: 'Heightened (+1) The damage increases by 1d4 and the weakness on a critical failure increases by 1.', },
  { id: 'gale-blast', name: 'Gale Blast', traits: ['Air', 'Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core 2 pg. 246', area: '5-foot emanation', defense: 'Fortitude', traditions: ['arcane', 'primal'], desc: 'Wind flows from your outstretched hands and whirls around you in a 5-foot emanation. Each creature in the area takes 1d6 bludgeoning damage, with a Fortitude save. Critical Success The creature is unaffected. Success The creature takes half damage. Failure The creature takes full damage and is pushed 5 feet away from you. Critical Failure The creature takes double damage and is pushed 10 feet away from you.', heightened: 'Heightened (+1) The damage increases by 1d6.', },
  { id: 'ghost-sound', name: 'Ghost Sound', traits: ['Auditory', 'Cantrip', 'Illusion'], source: 'Core Rulebook pg. 340', range: '30 feet', duration: 'sustained', traditions: ['arcane', 'occult'], desc: 'You create an auditory illusion of simple sounds that has a maximum volume equal to four normal humans shouting. The sounds emanate from a square you designate within range. You can\'t create intelligible words or other intricate sounds (such as music).', heightened: 'Heightened (3rd) The range increases to 60 feet. Heightened (5th) The range increases to 120 feet.', },
  { id: 'gouging-claw', name: 'Gouging Claw', traits: ['Attack', 'Cantrip', 'Concentrate', 'Manipulate', 'Morph'], source: 'Player Core pg. 333', range: 'touch', target: '1 creature', defense: 'AC', traditions: ['arcane', 'primal'], desc: 'You temporarily morph your limb into a clawed appendage. Make a melee spell attack roll against your target\'s AC. If you hit, you deal your choice of 2d6 slashing damage or 2d6 piercing damage, plus 2 persistent bleed damage. On a critical success, you deal double damage and double bleed damage.', heightened: 'Heightened (+1) The damage increases by 1d6 and the persistent bleed damage increases by 1.', },
  { id: 'guidance', name: 'Guidance', traits: ['Cantrip', 'Concentrate'], source: 'Player Core pg. 334', range: '30 feet', target: '1 creature', duration: 'until the start of your next turn', traditions: ['divine', 'occult', 'primal'], cast: 'Single Action', desc: 'You ask for the guidance of supernatural entities, granting the target a +1 status bonus to one attack roll, Perception check, saving throw, or skill check the target attempts before the duration ends. The target chooses which roll to use the bonus on before rolling. If the target uses the bonus, the spell ends. Either way, the target is then temporarily immune for 1 hour.', },
  { id: 'haunting-hymn', name: 'Haunting Hymn', traits: ['Auditory', 'Cantrip', 'Concentrate', 'Manipulate', 'Sonic'], source: 'Player Core 2 pg. 246', area: '15-foot cone', defense: 'basic Fortitude', traditions: ['divine', 'occult'], desc: 'You echo a jarring hymn that only creatures in the area can hear. The hymn deals 1d8 sonic damage, with a basic Fortitude save. If a target critically fails the save, it\'s also deafened for 1 minute.', heightened: 'Heightened (+2) The damage increases by 1d8.', },
  { id: 'ignition', name: 'Ignition', traits: ['Attack', 'Cantrip', 'Concentrate', 'Fire', 'Manipulate'], source: 'Player Core pg. 336', range: '30 feet', target: '1 creature', defense: 'AC', traditions: ['arcane', 'primal'], desc: 'You snap your fingers and point at a target, which begins to smolder. Make a spell attack roll against the target\'s AC, dealing 2d4 fire damage on a hit. If the target is within your melee reach, you can choose to make a melee spell attack with the flame instead of a ranged spell attack, which increases all the spell\'s damage dice to d6s. Critical Success The target takes double damage and 1d4 persistent fire damage. Success The target takes full damage.', heightened: 'Heightened (+1) The initial damage increases by 1d4 and the persistent fire damage on a critical hit increases by 1d4.', },
  { id: 'know-direction', name: 'Know Direction', traits: ['Cantrip', 'Detection', 'Divination'], source: 'Core Rulebook pg. 348', traditions: ['divine', 'occult', 'primal'], desc: 'In your mind\'s eye, you see a path northward. You immediately know which direction is north (if it exists at your current location).', heightened: 'Heightened (7th) You can instead know the direction to a familiar location, such as a previous home or a favorite tavern.', },
  { id: 'know-the-way', name: 'Know the Way', traits: ['Cantrip', 'Concentrate', 'Detection', 'Manipulate'], source: 'Player Core pg. 340', traditions: ['divine', 'occult', 'primal'], desc: 'In your mind\'s eye, you magically reorient yourself. You immediately know which direction is north (if it exists at your current location), and you can choose a location you were at within the last 24 hours and learn what direction it lies.', heightened: 'Heightened (3rd) You can choose a location you were at within the last week. Heightened (7th) You can choose a location you were at regardless of how long ago you were there.', },
  { id: 'light', name: 'Light', traits: ['Cantrip', 'Concentrate', 'Light', 'Manipulate'], source: 'Player Core pg. 340', range: '120 feet', duration: 'until your next daily preparations', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'You create an orb of light that sheds bright light in a 20-foot radius (and dim light for the next 20 feet) in a color you choose. If you create the light in the same space as a willing creature, you can attach the light to the creature, causing it to float near that creature as it moves. You can Sustain the spell to move the light up to 60 feet; you can attach or detach it from a creature as part of this movement. You can Dismiss the spell. If you Cast the Spell while you already have four light spells active, you must choose one of the existing spells to end.', heightened: 'Heightened (4th) The orb sheds light in a 60-foot radius (and dim light for the next 60 feet).', },
  { id: 'live-wire', name: 'Live Wire', traits: ['Attack', 'Cantrip', 'Concentrate', 'Electricity', 'Manipulate', 'Metal'], source: 'Player Core 2 pg. 248', range: '30 feet', target: '1 creature', defense: 'AC', traditions: ['arcane', 'primal'], desc: 'You conjure up a length of sharp copper filament humming with electrical current that strikes out at your foe. The wire deals 1d4 slashing damage and 1d4 electricity damage, depending on your spell attack roll against the target\'s AC. Critical Success The target takes double damage and 1d4 persistent electricity damage. Success The target takes full damage. Failure The target takes the electricity damage, but not the slashing damage. Critical Failure The target is unaffected.', heightened: 'Heightened (+2) The slashing damage, initial electricity damage, and persistent electricity damage on a critical hit each increase by 1d4.', },
  { id: 'mage-hand', name: 'Mage Hand', traits: ['Cantrip', 'Evocation'], source: 'Core Rulebook pg. 349', range: '30 feet', target: '1 unattended object of light Bulk or less', duration: 'sustained', traditions: ['arcane', 'occult'], desc: 'You create a single magical hand, either invisible or ghostlike, that grasps the target object and moves it slowly up to 20 feet. Because you\'re levitating the object, you can move it in any direction. When you Sustain the Spell, you can move the object an additional 20 feet. If the object is in the air when the spell ends, the object falls.', heightened: 'Heightened (3rd) You can target an unattended object with a Bulk of 1 or less. Heightened (5th) The range increases to 60 feet, and you can target an unattended object with a Bulk of 1 or less. Heightened (7th) The range increases to 60 feet, and you can target an unattended object with a Bulk of 2 or less.', },
  { id: 'message', name: 'Message', traits: ['Auditory', 'Cantrip', 'Concentrate', 'Illusion', 'Linguistic', 'Mental', 'Subtle'], source: 'Player Core pg. 343', range: '120 feet', target: '1 creature', duration: 'see below', traditions: ['arcane', 'divine', 'occult'], cast: 'Single Action', desc: 'You mouth words quietly, but instead of coming out of your mouth, they\'re transferred directly to the ears of the target. While others can\'t hear your words any better than if you normally mouthed them, the target can hear your words as if they were standing next to you. The target can give a brief response as a reaction, or as a free action on their next turn if they wish, but they must be able to see you and be within range to do so. If they respond, their response is delivered directly to your ear, just like the original message.', heightened: 'Heightened (3rd) The spell\'s range increases to 500 feet.', },
  { id: 'prestidigitation', name: 'Prestidigitation', traits: ['Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 351', range: '10 feet', target: '1 object (cook, lift, or tidy only)', duration: 'sustained', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'The simplest magic does your bidding. You can perform simple magical effects for as long as you Sustain the spell. Each time you Sustain the spell, you can choose one of four options. Cook Cool, warm, or flavor 1 pound of nonliving material. Lift Slowly lift an unattended object of light Bulk or less 1 foot off the ground. Make Create a temporary object of negligible Bulk, made of congealed magical substance. The object looks crude and artificial and is extremely fragile—it can\'t be used as a tool, weapon, or locus or cost for a spell. Tidy Color, clean, or soil an object of light Bulk or less. You can affect an object of 1 Bulk with 10 rounds of concentration, and a larger object a 1 minute per Bulk. Prestidigitation can\'t deal damage or cause adverse conditions. Any actual change to an object (beyond what is noted above) persists only as long as you Sustain the spell.', },
  { id: 'produce-flame', name: 'Produce Flame', traits: ['Attack', 'Cantrip', 'Evocation', 'Fire'], source: 'Core Rulebook pg. 360', range: '30 feet', target: '1 creature', traditions: ['arcane', 'primal'], desc: 'A small ball of flame appears in the palm of your hand, and you lash out with it either in melee or at range. Make a spell attack roll against your target\'s AC. This is normally a ranged attack, but you can also make a melee attack against a creature in your unarmed reach. The flame deals 2d4 fire damage. Critical Success The target takes double damage and 1d4 persistent fire damage. Success The target takes full damage.', heightened: 'Heightened (+1) Increase the damage by 1d4 and the persistent damage on a critical hit by 1d4.', },
  { id: 'puff-of-poison', name: 'Puff of Poison', traits: ['Cantrip', 'Concentrate', 'Manipulate', 'Poison'], source: 'Player Core 2 pg. 249', range: '10 feet', target: '1 creature', defense: 'Fortitude', traditions: ['arcane', 'primal'], desc: 'You exhale a shimmering cloud of toxic breath at an enemy\'s face. The target takes 1d4 poison damage and 1d4 persistent poison damage, depending on its Fortitude save. Critical Success The creature is unaffected. Success The target takes half initial damage and no persistent damage. Failure The target takes full initial and persistent damage. Critical Failure The target takes double initial and persistent damage.', heightened: 'Heightened (+2) The initial poison damage increases by 1d4, and the persistent poison damage increases by 1d4.', },
  { id: 'ray-of-frost', name: 'Ray of Frost', traits: ['Attack', 'Cantrip', 'Cold', 'Evocation'], source: 'Core Rulebook pg. 362', range: '120 feet', target: '1 creature', traditions: ['arcane', 'primal'], desc: 'You blast an icy ray. Make a spell attack roll. The ray deals 2d4 cold damage. Critical Success The target takes double damage and takes a –10-foot status penalty to its Speeds for 1 round. Success The target takes normal damage.', heightened: 'Heightened (+1) The damage increases by 1d4.', },
  { id: 'read-aura', name: 'Read Aura', traits: ['Cantrip', 'Concentrate', 'Detection', 'Manipulate'], source: 'Player Core pg. 352', range: '30 feet', target: '1 object', traditions: ['arcane', 'divine', 'occult', 'primal'], cast: '1 minute', desc: 'You focus on the target object, opening your mind to perceive magical auras. When the casting is complete, you know whether that item is magical. You or anyone you advise about the aura gains a +2 circumstance bonus to Identify Magic on the item. If the object is illusory, you detect this only if the effect\'s rank is lower than the rank of your read aura spell.', heightened: 'Heightened (3rd) You can target up to 10 objects. Heightened (6th) You can target any number of objects.', },
  { id: 'scatter-scree', name: 'Scatter Scree', traits: ['Cantrip', 'Concentrate', 'Earth', 'Manipulate'], source: 'Player Core 2 pg. 250', range: '30 feet', area: 'two contiguous 5-foot cubes', duration: '1 minute', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'A jumble of rocks cascades into the area. The scattering rocks deal 2d4 bludgeoning damage (basic Reflex save). The ground in the area becomes difficult terrain for the duration of the spell. A creature can Interact to clear a square of this scree. If you cast this spell again, any previous scatter scree you\'ve cast ends.', heightened: 'Heightened (+1) The damage increases by 1d4.', },
  { id: 'shield', name: 'Shield', traits: ['Cantrip', 'Concentrate', 'Force'], source: 'Player Core pg. 356', duration: 'until the start of your next turn', traditions: ['arcane', 'divine', 'occult'], cast: 'Single Action', desc: 'You raise a magical shield of force. This counts as using the Raise a Shield action, giving you a +1 circumstance bonus to AC until the start of your next turn, but it doesn\'t require a hand to use. While the spell is in effect, you can use the Shield Block reaction with your magic shield. The shield has Hardness 5. You can use the spell\'s reaction to reduce damage from any spell or magical effect, even if it doesn\'t deal physical damage. After you use Shield Block, the spell ends and you can\'t cast it again for 10 minutes.', heightened: 'Heightened (+2) The shield\'s Hardness increases by 5.', },
  { id: 'sigil', name: 'Sigil', traits: ['Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 357', range: 'touch', target: '1 creature or object', duration: 'unlimited (see below)', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'You harmlessly place your unique magical sigil, which is about 1 square inch in size, on the targeted creature or object. The mark can be visible or invisible, and you can change it from one state to another by using an Interact action to touch the target. The mark can be scrubbed or scraped off with 5 minutes of work. If it\'s on a creature, it fades naturally over the course of a week. The time before the mark fades increases depending on your heightened rank.', heightened: 'Heightened (3rd) The sigil instead fades after 1 month. Heightened (5th) The sigil instead fades after 1 year. Heightened (7th) The sigil never fades.', },
  { id: 'spout', name: 'Spout', traits: ['Cantrip', 'Concentrate', 'Manipulate', 'Water'], source: 'Player Core 2 pg. 252', range: '30 feet', area: 'a 5-foot cube', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'Water blasts upward, coming out of the ground, rising from a pool, or even manifesting from thin air. Any creatures in the area take 2d4 bludgeoning damage, with a basic Reflex saving throw. A creature that critically fails its save is disoriented by the explosion of water, becoming off-guard until the end of your next turn. You can change this spell\'s area to a 5-foot burst, provided you center the burst in a body of water. This body of water can be as small as a pond or creek, but not as small as a puddle or bathtub.', heightened: 'Heightened (+1) The damage increases by 1d4.', },
  { id: 'stabilize', name: 'Stabilize', traits: ['Cantrip', 'Concentrate', 'Healing', 'Manipulate', 'Vitality', 'Positive'], source: 'Player Core pg. 359', range: '30 feet', target: '1 dying creature', traditions: ['divine', 'primal'], desc: 'Life energy shuts death\'s door. The target loses the dying condition, though it remains unconscious at 0 Hit Points.', },
  { id: 'summon-instrument', name: 'Summon Instrument', traits: ['Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 361', duration: '1 hour', traditions: ['arcane', 'divine', 'occult'], cast: 'Three Actions', desc: 'You materialize a handheld musical instrument in your grasp. The instrument is typical for its type, but it plays for only you. It vanishes when the spell ends. If you cast summon instrument again, any instrument you previously summoned disappears.', heightened: 'Heightened (5th) The instrument is instead a virtuoso handheld instrument.', },
  { id: 'tangle-vine', name: 'Tangle Vine', traits: ['Attack', 'Cantrip', 'Concentrate', 'Manipulate', 'Plant', 'Wood'], source: 'Player Core pg. 362', range: '30 feet', target: '1 creature', defense: 'AC', traditions: ['arcane', 'primal'], desc: 'A vine appears from thin air, flicking from your hand and lashing itself to the target. Attempt a spell attack roll against the target. Critical Success The target gains the immobilized condition and takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to Escape against your spell DC to remove the penalty and the immobilized condition. Success The target takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to Escape against your spell DC to remove the penalty. Failure The target is unaffected.', heightened: 'Heightened (2nd) The effects last for 2 rounds. Heightened (4th) The effects last for 1 minute.', },
  { id: 'tanglefoot', name: 'Tanglefoot', traits: ['Attack', 'Cantrip', 'Conjuration', 'Plant'], source: 'Core Rulebook pg. 377', range: '30 feet', target: '1 creature', traditions: ['arcane', 'primal'], desc: 'A vine covered in sticky sap appears from thin air, flicking from your hand and lashing itself to the target. Attempt a spell attack against the target. Critical Success The target gains the immobilized condition and takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to Escape against your spell DC to remove the penalty and the immobilized condition. Success The target takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to Escape against your spell DC to remove the penalty. Failure The target is unaffected.', heightened: 'Heightened (2nd) The effects last for 2 rounds. Heightened (4th) The effects last for 1 minute.', },
  { id: 'telekinetic-hand', name: 'Telekinetic Hand', traits: ['Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 362', range: '30 feet', target: '1 unattended object of Light bulk or less', duration: 'sustained', traditions: ['arcane', 'occult'], desc: 'You create a floating, magical hand, either invisible or ghostlike, that grasps the target object and levitates it slowly up to 20 feet in any direction. When you Sustain the spell, you can move the object an additional 20 feet. If the object is in the air when the spell ends, the object falls.', heightened: 'Heightened (3rd) You can target an unattended object with a Bulk of 1 or less. Heightened (5th) The range increases to 60 feet, and you can target an unattended object with a Bulk of 1 or less. Heightened (7th) The range increases to 60 feet, and you can target an unattended object with a Bulk of 2 or less.', },
  { id: 'telekinetic-projectile', name: 'Telekinetic Projectile', traits: ['Attack', 'Cantrip', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 363', range: '30 feet', target: '1 creature', defense: 'AC', traditions: ['arcane', 'occult'], desc: 'You hurl a loose, unattended object that is within range and that has 1 Bulk or less at the target. Make a spell attack roll against the target\'s AC. If you hit, you deal 2d6 bludgeoning, piercing, or slashing damage—as appropriate for the object you hurled. No specific traits or magic properties of the hurled item affect the attack or the damage. Critical Success You deal double damage. Success You deal full damage.', heightened: 'Heightened (+1) The damage increases by 1d6.', },
  { id: 'vitality-lash', name: 'Vitality Lash', traits: ['Cantrip', 'Concentrate', 'Manipulate', 'Vitality', 'Positive'], source: 'Player Core pg. 366', range: '30 feet', target: '1 creature that is undead or otherwise has void healing', defense: 'basic Fortitude', traditions: ['divine', 'primal'], desc: 'You demolish the target\'s corrupted essence with energy from Creation\'s Forge. You deal 2d6 vitality damage with a basic Fortitude save. If the creature critically fails the save, it is also enfeebled 1 until the start of your next turn.', heightened: 'Heightened (+1) The damage increases by 1d6.', },
  { id: 'void-warp', name: 'Void Warp', traits: ['Cantrip', 'Concentrate', 'Manipulate', 'Void', 'Negative'], source: 'Player Core pg. 366', range: '30 feet', target: '1 living creature', defense: 'basic Fortitude', traditions: ['arcane', 'divine', 'occult'], desc: 'You call upon the Void to harm life force. The target takes 2d4 void damage with a basic Fortitude save. On a critical failure, the target is also enfeebled 1 until the start of your next turn.', heightened: 'Heightened (+1) The damage increases by 1d4.', },

  // Witch Patron hex cantrips (roadmap item 6 follow-up, v0.9.1). Each is
  // gated to one *specific* Patron (`patronId`, matching subclasses.js'
  // option ids), not freely pickable — a Witch's cantrips come from "the
  // spells your familiar knows" (Witch Spellcasting, Player Core pg. 178),
  // and at 1st level the familiar knows exactly one hex cantrip, whichever
  // one the chosen Patron grants. `traditions` still reflects each hex's
  // real tradition (from its Patron's Spell List) for glossary/display
  // consistency, but getSpellsForTradition() excludes any `patronId`-tagged
  // entry from the general pool — SpellsStep.jsx injects the one matching
  // the character's actual Patron directly instead, pre-selected and
  // locked (can't be deselected), the same "shown, not just described"
  // principle used for skills a subclass grants automatically.
  { id: 'clinging-ice', name: 'Clinging Ice', traits: ['Cantrip', 'Cold', 'Hex', 'Manipulate', 'Witch'], source: 'Player Core pg. 386', cast: 'Single Action', range: '30 feet', target: '1 creature', defense: 'Reflex', duration: 'sustained up to 1 minute', traditions: ['primal'], classId: 'witch', patronId: 'silence-in-snow', desc: "Freezing sleet and heavy snowfall collect on the target's feet and legs, dealing 1d4 cold damage and other effects depending on its Reflex save. Critical Success The target is unaffected. Success The target takes half damage. Failure The target takes full damage and a –5-foot circumstance penalty to its Speeds until the spell ends. Critical Failure The target takes double damage and a –10-foot circumstance penalty to its Speeds until the spell ends.", heightened: 'Heightened (+1) The damage increases by 1d4.', },
  { id: 'discern-secrets', name: 'Discern Secrets', traits: ['Cantrip', 'Hex', 'Manipulate', 'Witch'], source: 'Player Core pg. 386', cast: 'Single Action', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', traditions: ['arcane'], classId: 'witch', patronId: 'inscribed-one', desc: 'Your patron deigns to whisper a few secrets. The target can Recall Knowledge, Seek, or Sense Motive as a free action. The target gains a +1 status bonus to the statistic used for the roll (a skill or Perception) on the roll and as long as you Sustain the spell. The target is temporarily immune to discern secrets for 1 minute.', heightened: 'Heightened (5th) You can target two creatures instead of one.', },
  { id: 'evil-eye', name: 'Evil Eye', traits: ['Cantrip', 'Curse', 'Hex', 'Manipulate', 'Witch'], source: 'Player Core pg. 386', cast: 'Single Action', range: '30 feet', target: '1 creature', defense: 'Will', duration: 'sustained up to 1 minute', traditions: ['occult'], classId: 'witch', patronId: 'resentment', desc: "Your patron's resentment manifests in a baleful, envious gaze. The target becomes sickened 1 if it fails a Will save (or sickened 2 on a critical failure). This condition value can't be reduced below 1 while the spell is active and you can see the target.", },
  { id: 'nudge-fate', name: 'Nudge Fate', traits: ['Cantrip', 'Concentrate', 'Hex', 'Witch'], source: 'Player Core pg. 387', cast: 'Single Action', range: '30 feet', target: '1 creature', duration: '1 minute', traditions: ['occult'], classId: 'witch', patronId: 'spinner-of-threads', desc: "The barest spin of your patron's spool is enough to alter fate. When the target fails an attack roll, skill check, or saving throw and a +1 status bonus would turn a critical failure into a failure, or failure into a success, you grant the target a +1 status bonus to the check retroactively, changing the outcome appropriately. The spell then ends. If you cast nudge fate while a previous casting of this hex is still in effect, the previous effect ends.", },
  { id: 'shroud-of-night', name: 'Shroud of Night', traits: ['Cantrip', 'Darkness', 'Hex', 'Manipulate', 'Witch'], source: 'Player Core pg. 387', cast: 'Single Action', range: '30 feet', target: '1 creature', defense: 'Will', duration: 'sustained up to 1 minute', traditions: ['occult'], classId: 'witch', patronId: 'starless-shadow', desc: "Your patron blankets the target's eyes in darkness. If you cast this hex on a willing ally (for instance, one with light blindness), the ally can choose which result it gets without rolling. Success The target is unaffected. Failure The target is shrouded in murky darkness. It treats bright light as dim light, and unless it has greater darkvision, all creatures are concealed to it.", },
  { id: 'stoke-the-heart', name: 'Stoke the Heart', traits: ['Cantrip', 'Concentrate', 'Emotion', 'Hex', 'Witch'], source: 'Player Core pg. 387', cast: 'Single Action', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', traditions: ['divine'], classId: 'witch', patronId: 'faiths-flamekeeper', desc: 'Your patron fills a creature with fervor, empowering their blows. The target gains a +2 status bonus to damage rolls.', heightened: 'Heightened (+2) The status bonus to damage increases by 1.', },
  { id: 'wilding-word', name: 'Wilding Word', traits: ['Cantrip', 'Hex', 'Mental', 'Witch'], source: 'Player Core pg. 387', cast: 'Single Action', range: '30 feet', target: '1 creature', defense: 'Will', duration: 'sustained up to 1 minute', traditions: ['primal'], classId: 'witch', patronId: 'wilding-steward', desc: "Your patron's majesty—or their displeasure—comes in a growl from your throat, making other creatures reluctant to harm you. The target must attempt a Will save; if the creature is an animal, fungus, or plant, it takes a –1 circumstance penalty to its save. Critical Success The target is unaffected. Success When the target attempts an attack roll or skill check that would harm you, it takes a –2 status penalty to its roll. Failure As success, but the target also becomes sickened 1 each time it damages you. Critical Failure As failure, but the sickened value is 2.", },

  // Bard Composition cantrips (roadmap item 6 follow-up, v0.9.1): Uncommon +
  // Bard-trait spells every Bard has access to regardless of which Muse they
  // chose (the Muse instead grants one extra specific "Muse Spell" — see
  // subclasses.js — and, for some Muses, a feat). Occult tradition, gated to
  // Bard via `classId` since they're not open to every occult caster.
  { id: 'allegro', name: 'Allegro', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Emotion', 'Mental'], source: 'Player Core pg. 370', cast: 'Single Action', range: '30 feet', target: '1 ally', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: 'You perform rapidly, speeding up your ally. The ally becomes quickened and can use the additional action to Strike, Stride, or Step.', },
  { id: 'courageous-anthem', name: 'Courageous Anthem', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Emotion', 'Mental'], source: 'Player Core pg. 370', cast: 'Single Action', area: '60-foot emanation', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: 'You inspire yourself and your allies with words or tunes of encouragement. You and all allies in the area gain a +1 status bonus to attack rolls, damage rolls, and saves against fear effects.', },
  { id: 'dirge-of-doom', name: 'Dirge of Doom', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Emotion', 'Fear', 'Mental'], source: 'Player Core pg. 370', cast: 'Single Action', area: '30-foot emanation', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: "Enemies within the area are frightened 1. They can't reduce their frightened value below 1 while they remain in the area.", },
  { id: 'house-of-imaginary-walls', name: 'House of Imaginary Walls', traits: ['Bard', 'Cantrip', 'Composition', 'Illusion', 'Manipulate', 'Visual'], source: 'Player Core pg. 370', cast: 'Single Action', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: "You mime an invisible 10-foot-by-10-foot wall adjacent to you and within your reach. The wall is solid to those creatures that don't disbelieve it, even incorporeal creatures. You and your allies can voluntarily believe the wall exists to continue to treat it as solid, for instance to climb onto it. A creature that disbelieves the illusion is temporarily immune to your house of imaginary walls for 1 minute. The wall doesn't block creatures that didn't see your visual performance, nor does it block objects. The wall has AC 10, Hardness equal to double the spell's rank, and HP equal to quadruple the spell's rank.", },
  { id: 'rallying-anthem', name: 'Rallying Anthem', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Emotion', 'Mental'], source: 'Player Core pg. 371', cast: 'Single Action', area: '60-foot emanation', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: "Your song moves allies to protect themselves more effectively. You and all allies in the area gain a +1 status bonus to AC and saving throws, as well as resistance equal to half the spell's rank to physical damage.", },
  { id: 'song-of-marching', name: 'Song of Marching', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Mental'], source: 'Player Core pg. 371', cast: 'Single Action', area: '60-foot emanation', duration: 'sustained up to 1 hour', traditions: ['occult'], classId: 'bard', desc: 'You maintain a brisk performance that keeps allies on the move. You and your allies in the area can Hustle for the spell\'s duration, in addition to your other exploration activities (your exploration activity is Sustaining this spell). You and your allies then become temporarily immune for 1 day. If you enter an encounter while performing this song, you can use your Performance modifier for the initiative roll. You and your affected allies also receive a +1 status bonus to that initiative roll.', heightened: 'Heightened (6th) You can Sustain the Spell for up to 2 hours. Heightened (9th) You can Sustain the Spell for up to 4 hours.', },
  { id: 'song-of-strength', name: 'Song of Strength', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Emotion', 'Mental'], source: 'Player Core pg. 371', cast: 'Single Action', area: '60-foot emanation', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: "You bolster your allies' physical strength with a hearty exhortation. You and your allies gain a +1 status bonus to Athletics checks and to their DCs against Athletics skill actions such as Disarm, Reposition, Shove, and Trip.", },
  { id: 'triple-time', name: 'Triple Time', traits: ['Bard', 'Cantrip', 'Composition', 'Emotion', 'Manipulate', 'Mental'], source: 'Player Core pg. 372', cast: 'Single Action', area: '60-foot emanation', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: 'Your music sets a fast pace. You and all allies in the area gain a +10-foot status bonus to all Speeds for 1 round.', },
  { id: 'uplifting-overture', name: 'Uplifting Overture', traits: ['Bard', 'Cantrip', 'Composition', 'Concentrate', 'Emotion', 'Mental'], source: 'Player Core pg. 372', cast: 'Single Action', range: '60 feet', target: '1 ally', duration: '1 round', traditions: ['occult'], classId: 'bard', desc: "Your performance makes allies feel they can succeed at anything. This counts as having prepared to Aid your ally on a skill check of your choice. When you later use the Aid reaction, you can roll Performance instead of the normal skill check, and if you roll a failure, you get a success instead. If you are legendary in Performance, you automatically critically succeed. The GM might rule that you can't use this ability if the act of encouraging your ally would interfere with the skill check (such as a check to Sneak quietly or maintain a disguise).", },
];

export const SPELLS_RANK_1 = [
  { id: '500-toads', name: '500 Toads', traits: ['Concentrate', 'Manipulate', 'Rare'], source: 'NPC Core pg. 26', range: '30 feet', area: '15-foot burst', duration: '1 round', traditions: ['arcane', 'primal'], desc: 'You conjure hundreds of magical toads to fill the area and hop around. The vast quantity of hopping toads provides enough weight and height for the creatures to trigger any potential trap in the area that could be triggered by the weight, movement, or position of a Medium creature. The area is difficult terrain, and the magic reconstructs any toads destroyed by traps to keep the area full of toads for the duration of the spell.', },
  { id: 'air-bubble', name: 'Air Bubble', traits: ['Air', 'Concentrate'], source: 'Player Core pg. 314', range: '60 feet', target: 'the triggering creature', duration: '1 minute', traditions: ['arcane', 'divine', 'primal'], cast: 'Reaction', desc: 'A bubble of pure air appears around the target\'s head, allowing it to breathe normally. The effect ends as soon as the target returns to an environment where it can breathe normally.', },
  { id: 'alarm', name: 'Alarm', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 314', range: 'touch', area: '20-foot burst', duration: '8 hours', traditions: ['arcane', 'divine', 'occult', 'primal'], cast: '10 minutes', desc: 'You ward an area to alert you when creatures enter without your permission. When you cast alarm, select a password. Whenever a Small or larger corporeal creature enters the spell\'s area without speaking the password, alarm sends your choice of a mental alert (in which case the spell gains the mental trait) or an audible alarm with the sound and volume of a hand bell (in which case the spell gains the auditory trait). Either option automatically awakens you, and the bell allows each creature in the area to attempt a DC 15 Perception check to wake up. A creature aware of the alarm must succeed at a Stealth check against the spell\'s DC or trigger the spell when moving into the area.', heightened: 'Heightened (3rd) You can specify a trigger for which types of creatures sound the alarm spell, as described in Setting Triggers on page 303.', },
  { id: 'ant-haul', name: 'Ant Haul', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 315', range: 'touch', target: '1 creature', duration: '8 hours', traditions: ['arcane', 'primal'], desc: 'You reinforce the target\'s musculoskeletal system to bear more weight. The target can carry 3 more Bulk than normal before becoming encumbered and up to a maximum of 6 more Bulk.', },
  { id: 'bane', name: 'Bane', traits: ['Aura', 'Concentrate', 'Manipulate', 'Mental'], source: 'Player Core pg. 317', area: '10-foot emanation', duration: '1 minute', defense: 'Will', traditions: ['divine', 'occult'], desc: 'You fill the minds of your enemies with doubt. Enemies in the area must succeed at a Will save or take a –1 status penalty to attack rolls as long as they are in the area. Once per round on subsequent turns, you can Sustain the spell to increase the emanation\'s radius by 10 feet and force enemies in the area that weren\'t yet affected to attempt another saving throw. Bane can counteract bless.', },
  { id: 'bless', name: 'Bless', traits: ['Aura', 'Concentrate', 'Manipulate', 'Mental'], source: 'Player Core pg. 318', area: '15-foot emanation', duration: '1 minute', traditions: ['divine', 'occult'], desc: 'Blessings from beyond help your companions strike true. You and your allies gain a +1 status bonus to attack rolls while within the emanation. Once per round on subsequent turns, you can Sustain the spell to increase the emanation\'s radius by 10 feet. Bless can counteract bane.', },
  { id: 'breathe-fire', name: 'Breathe Fire', traits: ['Concentrate', 'Fire', 'Manipulate'], source: 'Player Core pg. 319', area: '15-foot cone', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'A gout of flame sprays from your mouth. You deal 2d6 fire damage to creatures in the area with a basic Reflex save.', heightened: 'Heightened (+1) The damage increases by 2d6.', },
  { id: 'burning-hands', name: 'Burning Hands', traits: ['Evocation', 'Fire'], source: 'Core Rulebook pg. 322', area: '15-foot cone', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'Gouts of flame rush from your hands. You deal 2d6 fire damage to creatures in the area.', heightened: 'Heightened (+1) The damage increases by 2d6.', },
  { id: 'carryall', name: 'Carryall', traits: ['Concentrate', 'Force', 'Manipulate'], source: 'Player Core 2 pg. 242', duration: '8 hours', traditions: ['arcane', 'occult'], desc: 'A small platform of magical force materializes adjacent to you to carry cargo. It is invisible or has a ghostly appearance, is 2 feet in diameter, and follows 5 feet behind you, floating just above the ground. It holds up to 5 Bulk of objects (if they can fit on it). Any objects atop the platform fall to the ground when the spell ends. You can Sustain the spell to move the platform up to 30 feet along the ground, to make it stay in place, or to have it return to you and resume following you. The spell ends if a creature tries to ride atop the platform, if the platform is overloaded, if anyone tries to lift or force the platform higher above the ground, or if you move more than 60 feet away from the platform.', heightened: 'Heightened (4th) The platform can carry 10 Bulk, creatures can ride atop it, and it can hover in the air, not just on the ground.', },
  { id: 'charm', name: 'Charm', traits: ['Concentrate', 'Emotion', 'Incapacitation', 'Manipulate', 'Mental', 'Subtle'], source: 'Player Core pg. 320', range: '30 feet', target: '1 creature', duration: '1 hour', defense: 'Will', traditions: ['arcane', 'occult', 'primal'], desc: 'To the target, your words are honey and your visage seems bathed in a dreamy haze. It must attempt a Will save, with a +4 circumstance bonus if you or your allies recently threatened it or used hostile actions against it. You can Dismiss the spell. If you use hostile actions against the target, the spell ends. When the spell ends, the target doesn\'t necessarily realize it was charmed unless its friendship with you or the actions you convinced it to take clash with its expectations, meaning you could potentially convince the target to continue being your friend via mundane means. Critical Success The target is unaffected and aware you tried to charm it. Success The target is unaffected but thinks your spell was something harmless instead of charm, unless it identifies the spell. Failure The target\'s attitude becomes friendly toward you. If it was friendly, it becomes helpful. It can\'t use hostile actions against you. Critical Failure The target\'s attitude becomes helpful toward you, and it can\'t use hostile actions against you.', heightened: 'Heightened (4th) The duration lasts until your next daily preparations. Heightened (8th) The duration lasts until your next daily preparations, and you can target up to 10 creatures.', },
  { id: 'chilling-spray', name: 'Chilling Spray', traits: ['Cold', 'Concentrate', 'Manipulate'], source: 'Player Core 2 pg. 242', area: '15-foot cone', defense: 'Reflex', traditions: ['arcane', 'primal'], desc: 'A cone of icy shards bursts from your spread hands and coats the targets in a layer of frost. You deal 2d4 cold damage to creatures in the area; they must each attempt a Reflex save. Critical Success The creature is unaffected. Success The creature takes half damage. Failure The creature takes full damage and takes a –5-foot status penalty to its Speeds for 2 rounds. Critical Failure The creature takes double damage and takes a –10-foot status penalty to its Speeds for 2 rounds.', heightened: 'Heightened (+1) The damage increases by 2d4.', },
  { id: 'cleanse-cuisine', name: 'Cleanse Cuisine', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 320', range: '10 feet', area: '1 cubic foot', traditions: ['divine', 'primal'], desc: 'You transform all food and beverages in the area into delicious fare, changing water into wine or another fine beverage, or enhancing the food\'s taste and ingredients to make it a gourmet treat. You can also choose to remove all toxins and contaminations from the food. This spell doesn\'t prevent future contamination, natural decay, or spoilage, nor does it make the food any more nutritious.', heightened: 'Heightened (+2) Add another cubic foot to the area, which must be contiguous with the rest.', },
  { id: 'color-spray', name: 'Color Spray', traits: ['Illusion', 'Incapacitation', 'Visual'], source: 'Core Rulebook pg. 324', area: '15-foot cone', duration: '1 or more rounds (see below)', defense: 'Will', traditions: ['arcane', 'occult'], desc: 'Swirling colors affect viewers based on their Will saves. Critical Success The creature is unaffected. Success The creature is dazzled for 1 round. Failure The creature is stunned 1, blinded for 1 round, and dazzled for 1 minute. Critical Failure The creature is stunned for 1 round and blinded for 1 minute.', },
  { id: 'command', name: 'Command', traits: ['Auditory', 'Concentrate', 'Linguistic', 'Manipulate', 'Mental'], source: 'Player Core pg. 321', range: '30 feet', target: '1 creature', duration: 'until the end of the target\'s next turn', defense: 'Will', traditions: ['arcane', 'divine', 'occult'], desc: 'You shout a command that\'s hard to ignore. You can command the target to approach you, run away (as if it had the fleeing condition), release what it\'s holding, drop prone, or stand in place. It can\'t Delay or take any reactions until it has obeyed your command. The effects depend on the target\'s Will save. Success The creature is unaffected. Failure The creature must spend the first action on its next turn to obey your command. Critical Failure The target must use all its actions on its next turn to obey your command.', heightened: 'Heightened (5th) You can target up to 10 creatures.', },
  { id: 'concordant-choir', name: 'Concordant Choir', traits: ['Concentrate', 'Sonic'], source: 'Player Core 2 pg. 243', range: '30 feet', target: 'varies', defense: 'basic Fortitude', traditions: ['divine', 'occult'], cast: '1-3 actions', desc: 'You unleash a dangerous consonance of reverberating sound, focusing on a single target or spreading out to damage many foes. The number of actions you spend Casting this Spell determines its targets, range, area, and other parameters. Single Action The spell deals 1d4 sonic damage to a single enemy, with a basic Fortitude save. Two Actions (manipulate) The spell deals 2d4 sonic damage to all creatures in a 10-foot burst, with a basic Fortitude save. Three Actions (manipulate) The spell deals 2d4 sonic damage to all creatures in a 30-foot emanation, with a basic Fortitude save', heightened: 'Heightened (+1) The damage increases by 1d4 for the 1-action version, or 2d4 for the other versions.', },
  { id: 'create-water', name: 'Create Water', traits: ['Concentrate', 'Manipulate', 'Water'], source: 'Player Core pg. 322', range: '0 feet', traditions: ['arcane', 'divine', 'primal'], desc: 'As you cup your hands, water begins to flow forth from them. You create 2 gallons of water. If no one drinks it, it evaporates after 1 day.', },
  { id: 'detect-alignment', name: 'Detect Alignment', traits: ['Detection', 'Divination', 'Uncommon'], source: 'Core Rulebook pg. 328', area: '30-foot emanation', traditions: ['divine', 'occult'], desc: 'Your eyes glow as you sense aligned auras. Choose chaotic, evil, good, or lawful. You detect auras of that alignment. You receive no information beyond presence or absence. You can choose not to detect creatures or effects you\'re aware have that alignment. Only creatures of 6th level or higher—unless divine spellcasters, undead, or beings from the Outer Sphere—have alignment auras.', heightened: 'Heightened (2nd) You learn each aura\'s location and strength.', },
  { id: 'detect-poison', name: 'Detect Poison', traits: ['Concentrate', 'Detection', 'Manipulate', 'Uncommon'], source: 'Player Core pg. 323', range: '30 feet', target: '1 object or creature', traditions: ['divine', 'primal'], desc: 'You detect whether a creature is venomous or poisonous, or if an object is poison or has been poisoned. You do not ascertain whether the target is poisonous in multiple ways, nor do you learn the type or types of poison. Certain substances, like lead and alcohol, are poisons and so mask other poisons.', heightened: 'Heightened (2nd) You learn the number and types of poison.', },
  { id: 'disguise-magic', name: 'Disguise Magic', traits: ['Concentrate', 'Illusion', 'Manipulate'], source: 'Player Core pg. 324', range: '30 feet', target: '1 item or spell effect', duration: 'until your next daily preparations', traditions: ['arcane', 'occult'], cast: '1 minute', desc: 'You alter how an item\'s or spell\'s magical aura appears to effects like detect magic. You can hide the auras entirely, have an item register as a common item of lower level, or make a spell register as a common spell of the same or lower rank. You can Dismiss the spell. A caster using detect magic or read aura of a higher rank than disguise magic can attempt to disbelieve the illusion using the skill matching the tradition of the spell (Arcana for arcane, Religion for divine, Occultism for occult, or Nature for primal). Further attempts by the same caster get the same result as the initial check to disbelieve.', heightened: 'Heightened (2nd) You can Cast this Spell on a creature, disguising all items and spell effects on it.', },
  { id: 'disrupting-weapons', name: 'Disrupting Weapons', traits: ['Necromancy', 'Positive', 'Vitality'], source: 'Core Rulebook pg. 331', range: 'touch', target: 'up to two weapons, each of which must be wielded by you or a willing ally, or else unattended', duration: '1 minute', traditions: ['divine'], desc: 'You infuse weapons with positive energy. Attacks with these weapons deal an extra 1d4 positive damage to undead.', heightened: 'Heightened (3rd) The damage increases to 2d4 damage. Heightened (5th) Target up to three weapons, and the damage increases to 3d4 damage.', },
  { id: 'dizzying-colors', name: 'Dizzying Colors', traits: ['Concentrate', 'Illusion', 'Incapacitation', 'Manipulate', 'Visual'], source: 'Player Core pg. 326', area: '15-foot cone', duration: '1 or more rounds (see below)', defense: 'Will', traditions: ['arcane', 'occult'], desc: 'You unleash a swirling multitude of colors that overwhelms creatures based on their Will saves. Critical Success The creature is unaffected. Success The creature is dazzled for 1 round. Failure The creature is stunned 1, blinded for 1 round, and dazzled for 1 minute. Critical Failure The creature is stunned for 1 round and blinded for 1 minute.', },
  { id: 'deja-vu', name: 'Déjà Vu', traits: ['Concentrate', 'Incapacitation', 'Manipulate', 'Mental'], source: 'Player Core 2 pg. 244', range: '100 feet', target: '1 creature', duration: '2 rounds', defense: 'Will', traditions: ['arcane', 'occult'], desc: 'You loop a thought process in the target\'s mind, forcing it to repeat a moment\'s worth of actions. The target must attempt a Will save. If the target fails, whatever actions the target uses on its next turn, it must repeat on its following turn. The actions must be repeated in the same order and as close to the same specifics as possible. For example, if the target makes an attack, it must repeat the attack against the same creature, if possible, and if the target moves, it must move the same distance and direction, if possible, on its next turn. If the target can\'t repeat an action, such as Casting a Spell that has been exhausted or needing to target a creature that has died, it can act as it chooses for that action but becomes stupefied 1 until the end of its turn.', },
  { id: 'enfeeble', name: 'Enfeeble', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 329', range: '30 feet', target: '1 creature', duration: 'varies', defense: 'Fortitude', traditions: ['arcane', 'divine', 'occult'], desc: 'You sap the target\'s strength, depending on its Fortitude save. Critical Success The target is unaffected. Success The target is enfeebled 1 until the start of your next turn. Failure The target is enfeebled 2 for 1 minute. Critical Failure The target is enfeebled 3 for 1 minute.', },
  { id: 'fear', name: 'Fear', traits: ['Concentrate', 'Emotion', 'Fear', 'Manipulate', 'Mental'], source: 'Player Core pg. 331', range: '30 feet', target: '1 creature', duration: 'varies', defense: 'Will', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'You plant fear in the target; it must attempt a Will save. Critical Success The target is unaffected. Success The target is frightened 1. Failure The target is frightened 2. Critical Failure The target is frightened 3 and fleeing for 1 round.', heightened: 'Heightened (3rd) You can target up to five creatures.', },
  { id: 'feather-fall', name: 'Feather Fall', traits: ['Abjuration'], source: 'Core Rulebook pg. 337', range: '60 feet', target: '1 falling creature', duration: '1 minute', traditions: ['arcane', 'primal'], cast: 'Reaction', desc: 'You cause the air itself to arrest a fall. The target\'s fall slows to 60 feet per round, and the portion of the fall during the spell\'s duration doesn\'t count when calculating falling damage. If the target reaches the ground while the spell is in effect, it takes no damage from the fall. The spell ends as soon as the target lands.', },
  { id: 'fleet-step', name: 'Fleet Step', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 332', duration: '1 minute', traditions: ['arcane', 'primal'], desc: 'You gain a +30-foot status bonus to your Speed.', },
  { id: 'floating-disk', name: 'Floating Disk', traits: ['Conjuration', 'Force'], source: 'Core Rulebook pg. 339', duration: '8 hours', traditions: ['arcane', 'occult'], desc: 'A disk of magical force materializes adjacent to you. This disk is 2 feet in diameter and follows 5 feet behind you, floating just above the ground. It holds up to 5 Bulk of objects (though they must be able to fit and balance on its surface). Any objects atop the disk fall to the ground when the spell ends. The spell ends if a creature tries to ride atop the disk, if the disk is overloaded, if anyone tries to lift or force the disk higher above the ground, or if you move more than 30 feet away from the disk.', },
  { id: 'force-barrage', name: 'Force Barrage', traits: ['Concentrate', 'Force', 'Manipulate'], source: 'Player Core pg. 332', range: '120 feet', target: '1 creature', traditions: ['arcane', 'occult'], cast: '1-3 actions', desc: 'You fire a shard of solidified magic toward a creature that you can see. It automatically hits and deals 1d4+1 force damage. For each additional action you use when Casting the Spell, increase the number of shards you shoot by one, to a maximum of three shards for 3 actions. You choose the target for each shard individually. If you shoot more than one shard at the same target, combine the damage before applying bonuses or penalties to damage, resistances, weaknesses, and so forth.', heightened: 'Heightened (+2) You fire one additional shard with each action you spend.', },
  { id: 'gentle-landing', name: 'Gentle Landing', traits: ['Air', 'Concentrate'], source: 'Player Core pg. 333', range: '60 feet', target: '1 falling creature', duration: '1 minute', traditions: ['arcane', 'primal'], cast: 'Reaction', desc: 'You raise a magical updraft to arrest a fall. The target\'s fall slows to 60 feet per round, and the portion of the fall during the spell\'s duration doesn\'t count when calculating falling damage. If the target reaches the ground while the spell is in effect, it takes no damage from the fall. The spell ends as soon as the target lands.', },
  { id: 'goblin-pox', name: 'Goblin Pox', traits: ['Concentrate', 'Disease', 'Manipulate'], source: 'Player Core pg. 333', range: 'touch', target: '1 creature', defense: 'Fortitude', traditions: ['arcane', 'primal'], desc: 'Your touch afflicts the target with goblin pox, an irritating allergenic rash. The target must attempt a Fortitude save. Critical Success The target is unaffected. Success The target is sickened 1. Failure The target is afflicted with goblin pox at stage 1. Critical Failure The target is afflicted with goblin pox at stage 2. Goblin Pox (disease) Level 1; Creatures that have the goblin trait and goblin dogs are immune; Stage 1 sickened 1 (1 round); Stage 2 sickened 1 and slowed 1 (1 round); Stage 3 sickened 1 and the creature can\'t reduce its sickened value below 1 (1 day)', },
  { id: 'grease', name: 'Grease', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 333', range: '30 feet', area: '4 contiguous 5-foot squares or', target: '1 object of 1 Bulk or less', duration: '1 minute', traditions: ['arcane', 'primal'], desc: 'You conjure grease, choosing an area or target. Area All solid ground in the area is covered with grease. Each creature standing on the greasy surface must succeed at a Reflex save or an Acrobatics check against your spell DC or fall prone. Creatures using an action to move onto the greasy surface during the spell\'s duration must attempt either a Reflex save or an Acrobatics check to Balance. A creature that Steps or Crawls doesn\'t have to attempt a check or save. Target If you Cast the Spell on an unattended object, anyone trying to pick up the object must succeed at an Acrobatics check or Reflex save against your spell DC to do so. If you target an attended object, the creature that has the object must attempt an Acrobatics check or Reflex save. On a failure, the holder or wielder takes a –2 circumstance penalty to all checks that involve using the object; on a critical failure, the holder or wielder releases the item. The object lands in an adjacent square of the GM\'s choice. If you Cast this Spell on a worn object, the wearer gains a +2 circumstance bonus to Fortitude saves against attempts to grapple them.', },
  { id: 'grim-tendrils', name: 'Grim Tendrils', traits: ['Concentrate', 'Manipulate', 'Void', 'Negative'], source: 'Player Core pg. 334', area: '30-foot line', defense: 'Fortitude', traditions: ['arcane', 'occult'], desc: 'Tendrils of darkness curl out from your fingertips and race through the air. You deal 2d4 void damage and 1 persistent bleed damage to living creatures in the line. Each living creature in the line must attempt a Fortitude save. Critical Success The creature is unaffected. Success The creature takes half the void damage and no persistent bleed damage. Failure The creature takes full damage. Critical Failure The creature takes double void damage and double persistent bleed damage.', heightened: 'Heightened (+1) The void damage increases by 2d4, and the persistent bleed damage increases by 1.', },
  { id: 'gust-of-wind', name: 'Gust of Wind', traits: ['Air', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 334', area: '60-foot line', duration: 'until the start of your next turn', defense: 'Fortitude', traditions: ['arcane', 'primal'], desc: 'A violent wind issues forth from your palm, blowing from the point where you are when you Cast the Spell to the line\'s opposite end. The wind extinguishes small non-magical fires, disperses fog and mist, blows objects of light Bulk or less around, and pushes larger objects. Large or smaller creatures in the area must attempt a Fortitude save. Large or smaller creatures that later move into the gust must attempt the save on entering. Critical Success The creature is unaffected. Success The creature can\'t move against the wind. Failure The creature is knocked prone. If it was flying, it takes the effects of critical failure instead. Critical Failure The creature is pushed 30 feet in the wind\'s direction, knocked prone, and takes 2d6 bludgeoning damage.', },
  { id: 'harm', name: 'Harm', traits: ['Manipulate', 'Void', 'Negative'], source: 'Player Core pg. 334', range: 'varies', target: '1 living creature or 1 willing undead creature', traditions: ['divine'], cast: '1-3 actions', desc: 'You channel void energy to harm the living or heal the undead. If the target is a living creature, you deal 1d8 void damage to it, and it gets a basic Fortitude save. If the target is a willing undead creature, you restore that amount of Hit Points. The number of actions you spend when Casting this Spell determines its targets, range, area, and other parameters. Single Action The spell has a range of touch. Two Actions (concentrate) The spell has a range of 30 feet. If you\'re healing an undead creature, increase the Hit Points restored by 8. Three Actions (concentrate) You disperse void energy in a 30-foot emanation. This targets all living and undead creatures in the area.', heightened: 'Heightened (+1) The amount of healing or damage increases by 1d8, and the extra healing for the 2-action version increases by 8.', },
  { id: 'heal', name: 'Heal', traits: ['Healing', 'Manipulate', 'Vitality', 'Positive'], source: 'Player Core pg. 335', range: 'varies', target: '1 willing living creature or 1 undead creature', traditions: ['divine', 'primal'], cast: '1-3 actions', desc: 'You channel vital energy to heal the living or damage the undead. If the target is a willing living creature, you restore 1d8 Hit Points. If the target is undead, you deal that amount of vitality damage to it, and it gets a basic Fortitude save. The number of actions you spend when Casting this Spell determines its targets, range, area, and other parameters. Single Action The spell has a range of touch. Two Actions (concentrate) The spell has a range of 30 feet. If you\'re healing a living creature, increase the Hit Points restored by 8. Three Actions (concentrate) You disperse vital energy in a 30-foot emanation. This targets all living and undead creatures in the burst.', heightened: 'Heightened (+1) The amount of healing or damage increases by 1d8, and the extra healing for the 2-action version increases by 8.', },
  { id: 'hydraulic-push', name: 'Hydraulic Push', traits: ['Attack', 'Concentrate', 'Manipulate', 'Water'], source: 'Player Core pg. 336', range: '60 feet', target: '1 creature or unattended object', defense: 'AC', traditions: ['arcane', 'primal'], desc: 'You call forth a powerful blast of pressurized water that bludgeons the target and knocks it back. Make a ranged spell attack roll. Critical Success The target takes 6d6 bludgeoning damage and is knocked back 10 feet. Success The target takes 3d6 bludgeoning damage and is knocked back 5 feet.', heightened: 'Heightened (+1) The bludgeoning damage increases by 2d6.', },
  { id: 'ill-omen', name: 'Ill Omen', traits: ['Concentrate', 'Curse', 'Manipulate', 'Misfortune'], source: 'Player Core pg. 336', range: '30 feet', target: '1 creature', duration: '1 round', defense: 'Will', traditions: ['occult'], desc: 'The target is struck with misfortune, which throws it off balance. The target must attempt a Will save. Success The target is unaffected. Failure The first time during the duration that the target attempts an attack roll or skill check, it must roll twice and use the worse result. Critical Failure Every time during the duration that the target attempts an attack roll or skill check, it must roll twice and use the worse result.', },
  { id: 'illusory-disguise', name: 'Illusory Disguise', traits: ['Concentrate', 'Illusion', 'Manipulate', 'Visual'], source: 'Player Core pg. 337', range: '30 feet', target: '1 willing creature', duration: '1 hour', traditions: ['arcane', 'occult'], desc: 'You create an illusion that causes the target to appear as another creature of the same body shape, and with roughly similar height (within 6 inches) and weight (within 50 pounds). The disguise is typically good enough to hide their identity, but not to impersonate a specific individual. The spell changes their appearance and voice, but not mannerisms. You can change the appearance of its clothing and worn items, such as making its armor look like a dress. Held items are unaffected, and any worn item removed from the creature returns to its true appearance. Casting illusory disguise counts as setting up a disguise for the Impersonate use of Deception; it ignores any circumstance penalties the target might take for disguising itself as a dissimilar creature, gives a +4 status bonus to Deception checks to prevent others from seeing through the disguise, and lets the target add its level to such Deception checks even if untrained. You can Dismiss this spell.', heightened: 'Heightened (3rd) The target can appear as any creature of the same size, even a specific individual. You must have seen an individual to replicate its appearance, and must have heard its voice to replicate its voice. Heightened (4th) You can target up to 10 willing creatures. If you target multiple creatures, you can choose a different disguise for each target, but none can impersonate a specific individual. You can Dismiss each disguise individually or all collectively. Heightened (7th) As 4th, but you can choose disguises that impersonate specific individuals. You must have seen an individual to replicate its appearance, and must have heard its voice to replicate its voice.', },
  { id: 'illusory-object', name: 'Illusory Object', traits: ['Concentrate', 'Illusion', 'Manipulate', 'Visual'], source: 'Player Core pg. 337', range: '500 feet', area: '20-foot burst', duration: '10 minutes', traditions: ['arcane', 'occult'], desc: 'You create an illusory visual image of a stationary object. The entire image must fit within the spell\'s area. The object appears to animate naturally, but it doesn\'t make sounds or generate smells. For example, water would appear to pour down an illusory waterfall, but it would be silent. Any creature that touches the image or uses the Seek action to examine it can attempt to disbelieve your illusion.', heightened: 'Heightened (2nd) Your image makes appropriate sounds, generates normal smells, and feels right to the touch. The spell gains the auditory and olfactory traits. The duration increases to 1 hour. Heightened (5th) As the 2nd-rank version, but the duration is unlimited.', },
  { id: 'imprint-message', name: 'Imprint Message', traits: ['Concentrate', 'Manipulate'], source: 'Player Core 2 pg. 247', range: 'touch', target: '1 object', traditions: ['occult'], desc: 'You project psychic vibrations onto the target object, imprinting it with a short message or emotional theme of your design. This imprinted sensation is revealed to a creature who casts object reading on the target object, replacing any emotional events the item was present for. If the object is in the area of a retrocognition spell, the imprinted messages appear as major events in the timeline, but they don\'t interfere with any other visions. If the object is targeted with read aura of a higher spell rank than imprint message, the caster learns that the object has been magically modified. When you Cast this Spell, any prior vibrations placed on an object by previous castings of imprint message fade.', },
  { id: 'infuse-vitality', name: 'Infuse Vitality', traits: ['Concentrate', 'Manipulate', 'Vitality', 'Positive'], source: 'Player Core pg. 338', range: '30 feet', target: '1 to 3 willing creatures', duration: '1 minute', traditions: ['divine'], cast: '1-3 actions', desc: 'You empower attacks with vital energy. The number of targets is equal to the number of actions you spent casting this spell. Each target\'s unarmed and weapon Strikes deal an extra 1d4 vitality damage. (This damage typically damages only undead.) If you have the holy trait, you can add that trait to this spell and to the Strikes affected by the spell.', heightened: 'Heightened (3rd) The damage increases to 2d4 damage. Heightened (5th) The damage increases to 3d4 damage.', },
  { id: 'invisible-item', name: 'Invisible Item', traits: ['Concentrate', 'Illusion', 'Manipulate'], source: 'Player Core 2 pg. 247', range: 'touch', target: '1 object', duration: '1 hour', traditions: ['arcane', 'occult'], desc: 'You make the object invisible. This makes it undetected to all creatures, though the creatures can attempt to find the target, making it hidden to them instead if they succeed. If the item is used as part of a hostile action, the spell ends after that hostile action is completed. Making a weapon invisible typically doesn\'t give any advantage to the attack, except that an invisible thrown weapon or piece of ammunition can be used for an attack without necessarily giving information about the attacker\'s hiding place unless the weapon returns to the attacker.', heightened: 'Heightened (3rd) The duration is until the next time you make your daily preparations. Heightened (7th) The duration is unlimited.', },
  { id: 'item-facade', name: 'Item Facade', traits: ['Concentrate', 'Illusion', 'Manipulate', 'Visual'], source: 'Player Core pg. 340', range: 'touch', target: '1 object no more than 10 feet by 10 feet by 10 feet', duration: '1 hour', traditions: ['arcane', 'occult'], desc: 'You make the target object look and feel as though it were in much better or worse physical condition. When you Cast this Spell, decide whether you want to make the object look decrepit or perfect. An item made to look decrepit appears broken and shoddy. An intact item made to look better appears as though it\'s brand new and highly polished or well maintained. A broken item appears to be intact and functional. Destroyed items can\'t be affected by this spell. A creature that Interacts with the item can attempt to disbelieve the illusion.', heightened: 'Heightened (2nd) The duration is 24 hours. Heightened (3rd) The duration is unlimited.', },
  { id: 'jump', name: 'Jump', traits: ['Manipulate', 'Move'], source: 'Player Core pg. 340', traditions: ['arcane', 'primal'], cast: 'Single Action', desc: 'Your legs surge with strength, ready to leap high and far. You jump 30 feet in any direction without touching the ground. You must land on a space of solid ground within 30 feet of you, or else you fall after using your next action.', heightened: 'Heightened (3rd) The range becomes touch, the target changes to one touched creature, and the duration becomes 1 minute, allowing the target to jump as described whenever it takes the Leap action.', },
  { id: 'leaden-steps', name: 'Leaden Steps', traits: ['Concentrate', 'Manipulate', 'Metal', 'Morph'], source: 'Player Core 2 pg. 247', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', defense: 'Fortitude', traditions: ['arcane', 'primal'], desc: 'You partially transform a foe\'s feet into unwieldy slabs of metal, slowing their steps. The target attempts a Fortitude saving throw. Critical Success The target is unaffected. Success The target is encumbered and has weakness 2 to electricity until the end of your next turn. The spell can\'t be sustained. Failure The target is encumbered and has weakness 2 to electricity. Critical Failure The target is encumbered and has weakness 3 to electricity.', heightened: 'Heightened (+1) The weakness increases by 1.', },
  { id: 'lock', name: 'Lock', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 341', range: 'touch', target: '1 lock, or a door or container with a latch', duration: 'until your next daily preparations', traditions: ['arcane', 'divine', 'occult'], desc: 'The target\'s latch mechanism clinks shut, held fast by unseen magical wards. When you magically lock a target, you set an Athletics and Thievery DC to open it equal to your spell DC or the base lock DC with a +4 status bonus, whichever is higher. Any key or combination that once opened a lock affected by this spell does not do so for the duration of the spell, though the key or combination does grant a +4 circumstance bonus to checks to open the door. If the target is opened, the spell ends. Assuming the target is not barred or locked in some additional way, you can unlock and open it with an Interact action during which you touch the target. This does not end the spell. You can Dismiss this spell at any time and from any distance.', heightened: 'Heightened (2nd) The duration is unlimited, but you must expend 6 gp worth of precious metals as an additional cost.', },
  { id: 'longstrider', name: 'Longstrider', traits: ['Transmutation'], source: 'Core Rulebook pg. 348', duration: '1 hour', traditions: ['arcane', 'primal'], desc: 'You lengthen your stride beyond what should be possible. You gain a +10-foot status bonus to your Speed.', heightened: 'Heightened (2nd) The duration increases to 8 hours.', },
  { id: 'mage-armor', name: 'Mage Armor', traits: ['Abjuration'], source: 'Core Rulebook pg. 348', duration: 'until the next time you make your daily preparations', traditions: ['arcane', 'occult'], desc: 'You ward yourself with shimmering magical energy, gaining a +1 item bonus to AC and a maximum Dexterity modifier of +5. While wearing mage armor, you use your unarmored proficiency to calculate your AC.', heightened: 'Heightened (4th) You gain a +1 item bonus to saving throws. Heightened (6th) The item bonus to AC increases to +2, and you gain a +1 item bonus to saving throws. Heightened (8th) The item bonus to AC increases to +2, and you gain a +2 item bonus to saving throws. Heightened (10th) The item bonus to AC increases to +3, and you gain a +3 item bonus to saving throws.', },
  { id: 'magic-aura', name: 'Magic Aura', traits: ['Illusion', 'Uncommon'], source: 'Core Rulebook pg. 349', range: 'touch', target: '1 object of 3 bulk or less', duration: 'until the next time you make your daily preparations', traditions: ['arcane', 'occult'], cast: '1 minute', desc: 'You alter the appearance of an item\'s magic aura. You can choose to have the target\'s aura appear as that of a common magic item of twice magic aura\'s level or lower, or to have it register as being under the effects of a spell of your choice of magic aura\'s level or lower. If the target is magical, you can instead choose to have it appear as entirely non-magical. A caster using detect magic or read aura of an equal or higher spell level can attempt to disbelieve the illusion from magic aura. Magic aura doesn\'t mask the aura of spells that are 9th level or higher or of items that are 19th level or higher.', heightened: 'Heightened (3rd) You can target a creature instead of an object. When you do, you can either conceal the auras of all magic items it has or have that creature\'s aura appear as if it were under the effect of a spell you know.', },
  { id: 'magic-fang', name: 'Magic Fang', traits: ['Transmutation'], source: 'Core Rulebook pg. 349', range: 'touch', target: '1 willing creature', duration: '1 minute', traditions: ['primal'], desc: 'Choose one of the target\'s unarmed attacks. You cause that unarmed attack to shine with primal energy. The unarmed attack becomes a +1 striking unarmed attack, gaining a +1 item bonus to attack rolls and increasing the number of damage dice to two if it had only one.', },
  { id: 'magic-missile', name: 'Magic Missile', traits: ['Evocation', 'Force'], source: 'Core Rulebook pg. 349', range: '120 feet', target: '1 creature', traditions: ['arcane', 'occult'], cast: '1-3 actions', desc: 'You send a dart of force streaking toward a creature that you can see. It automatically hits and deals 1d4+1 force damage. For each additional action you use when Casting the Spell, increase the number of missiles you shoot by one, to a maximum of three missiles for 3 actions. You choose the target for each missile individually. If you shoot more than one missile at the same target, combine the damage before applying bonuses or penalties to damage, resistances, weaknesses, and so forth.', heightened: 'Heightened (+2) You shoot one additional missile with each action you spend.', },
  { id: 'magic-weapon', name: 'Magic Weapon', traits: ['Transmutation'], source: 'Core Rulebook pg. 349', range: 'touch', target: '1 weapon that is unattended or wielded by you or a willing ally', duration: '1 minute', traditions: ['arcane', 'divine', 'occult'], desc: 'The weapon glimmers with magic and energy. The target becomes a +1 striking weapon, gaining a +1 item bonus to attack rolls and increasing the number of weapon damage dice to two.', },
  { id: 'mending', name: 'Mending', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 343', range: 'touch', target: 'non-magical object of light Bulk or less', traditions: ['arcane', 'divine', 'occult', 'primal'], cast: '10 minutes', desc: 'You repair the target item. You restore 5 Hit Points per spell rank to the target, potentially removing the broken condition if this repairs it past the item\'s Broken Threshold. You can\'t replace lost pieces or repair an object that\'s been completely destroyed.', heightened: 'Heightened (2nd) You can target a non-magical object of 1 Bulk or less. Heightened (3rd) You can target a non-magical object of 2 Bulk or less, or a magical object of 1 Bulk or less.', },
  { id: 'mindlink', name: 'Mindlink', traits: ['Concentrate', 'Manipulate', 'Mental'], source: 'Player Core pg. 344', range: 'touch', target: '1 willing creature', traditions: ['occult'], desc: 'You link your mind to the target\'s mind and mentally impart to that target an amount of information in an instant that could otherwise be communicated in 10 minutes.', },
  { id: 'mud-pit', name: 'Mud Pit', traits: ['Concentrate', 'Earth', 'Manipulate', 'Water'], source: 'Player Core 2 pg. 248', range: '60 feet', area: 'squares on the ground in a 15-foot burst', duration: '1 minute', traditions: ['arcane', 'primal'], cast: 'Three Actions', desc: 'Thick, clinging mud covers the ground, 1 foot deep. The mud is difficult terrain.', },
  { id: 'mystic-armor', name: 'Mystic Armor', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 346', duration: 'until your next daily preparations', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'You ward yourself with shimmering magical energy, gaining a +1 item bonus to AC and a maximum Dexterity modifier of +5. While wearing mystic armor, you use your unarmored proficiency to calculate your AC.', heightened: 'Heightened (4th) You gain a +1 item bonus to saving throws. Heightened (6th) The item bonus to AC increases to +2, and you gain a +1 item bonus to saving throws. Heightened (8th) The item bonus to AC increases to +2, and you gain a +2 item bonus to saving throws. Heightened (10th) The item bonus to AC increases to +3, and you gain a +3 item bonus to saving throws.', },
  { id: 'negate-aroma', name: 'Negate Aroma', traits: ['Abjuration'], source: 'Core Rulebook pg. 354', range: 'touch', target: '1 willing creature', duration: '1 hour', traditions: ['arcane', 'primal'], desc: 'The target loses its odor, preventing creatures from passively noticing its presence via smell alone, even if the creatures have precise or imprecise scent. A creature attempting a Perception check to Seek with scent and other senses might notice the lack of natural scent. If the target has any abilities that result from its smell, such as an overpowering scent, those abilities are also negated.', heightened: 'Heightened (5th) The range increases to 30 feet, and you can target up to 10 creatures.', },
  { id: 'noxious-vapors', name: 'Noxious Vapors', traits: ['Concentrate', 'Manipulate', 'Poison'], source: 'Player Core 2 pg. 248', area: '10-foot emanation', duration: '1 round', defense: 'basic Fortitude', traditions: ['arcane', 'primal'], desc: 'You emit a cloud of toxic smoke that temporarily obscures you from sight. Each creature except you in the area when you Cast the Spell takes 1d6 poison damage (basic Fortitude save). A creature that critically fails the saving throw also becomes sickened 1. All creatures in the area become concealed, and all creatures outside the smoke become concealed to creatures within it. This smoke can be dispersed by a strong wind.', heightened: 'Heightened (+1) The damage increases by 1d6.', },
  { id: 'object-reading', name: 'Object Reading', traits: ['Concentrate', 'Manipulate'], source: 'Player Core 2 pg. 248', range: 'touch', target: '1 object', traditions: ['occult'], desc: 'You place a hand on an object to learn a piece of information about an emotional event that occurred involving the object within the past week, determined by the GM. If you cast object reading on the same item multiple times, you can either concentrate on a single event to gain additional pieces of information about that event or gain a piece of information about another emotional event in the applicable time frame.', heightened: 'Heightened (2nd) You can learn about an event that occurred within the last month. Heightened (4th) You can learn about an event that occurred within the last year. Heightened (6th) You can learn about an event that occurred within the last decade. Heightened (8th) You can learn about an event that occurred within the last century. Heightened (9th) You can learn about an event that occurred within the entirety of the object\'s history.', },
  { id: 'pass-without-trace', name: 'Pass Without Trace', traits: ['Abjuration'], source: 'Core Rulebook pg. 356', duration: '1 hour', traditions: ['primal'], desc: 'You obscure the tracks you leave behind and make it harder for others to find you. The DC of checks to Track you gains a +4 status bonus or is equal to your spell DC, whichever results in a higher DC. You can benefit from only one pass without trace spell at a time.', heightened: 'Heightened (2nd) The duration increases to 8 hours. Heightened (4th) The duration increases to 8 hours. The spell has a range of 20 feet and an area of a 20-foot-emanation, affecting up to 10 creatures of your choice within that area.', },
  { id: 'pest-form', name: 'Pest Form', traits: ['Concentrate', 'Manipulate', 'Polymorph'], source: 'Player Core pg. 348', duration: '10 minutes', traditions: ['arcane', 'primal'], desc: 'You transform into the battle form of a Tiny animal, such as a cat, insect, lizard, or rat. You can decide the specific type of animal (such as a rat or praying mantis), but this has no effect on your Size or statistics. While in this form, you gain the animal trait, and you can\'t make Strikes. You can Dismiss the spell. You gain the following statistics and abilities: AC = 15 + your level. Ignore your armor\'s check penalty and Speed reduction. Speed 20 feet. Weakness 5 to physical damage. (If you take physical damage in this form, you take 5 additional damage.) Low-light vision and imprecise scent 30 feet. Acrobatics and Stealth modifiers of +10, unless your own is higher; Athletics modifier –4.', heightened: 'Heightened (4th) You can turn into a flying creature, such as a bird, which grants you a fly Speed of 20 feet.', },
  { id: 'pet-cache', name: 'Pet Cache', traits: ['Extradimensional', 'Manipulate'], source: 'Player Core pg. 348', range: 'touch', target: '1 willing creature that is your companion', duration: '8 hours', traditions: ['arcane', 'divine', 'occult', 'primal'], cast: 'Single Action', desc: 'You open your cloak or create a gap with your hands, drawing the target into a pocket dimension just large enough for its basic comfort. No other creature can enter this extradimensional space, and the target can bring along objects only if they were designed to be worn by a creature of its kind. The space has enough air, food, and water to sustain the target for the duration. You can Dismiss the spell. The spell also ends if you die or enter an extradimensional space. When the spell ends, the target reappears in the nearest unoccupied space (outside of any extradimensional space you may have entered).', },
  { id: 'phantasmal-minion', name: 'Phantasmal Minion', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core pg. 349', range: '60 feet', duration: 'sustained', traditions: ['arcane', 'occult'], cast: 'Three Actions', desc: 'You summon a phantasmal minion. The minion is roughly the shape of a humanoid. You can choose to have it be invisible or have an ephemeral appearance, but it\'s obviously a magical effect, not a real creature.', },
  { id: 'phantom-pain', name: 'Phantom Pain', traits: ['Concentrate', 'Illusion', 'Manipulate', 'Mental', 'Nonlethal'], source: 'Player Core pg. 349', range: '30 feet', target: '1 creature', duration: '1 minute', defense: 'Will', traditions: ['occult'], desc: 'Illusory pain wracks the target, dealing 2d4 mental damage and 1d4 persistent mental damage with a Will save. Critical Success The target is unaffected. Success The target takes full initial damage but no persistent damage, and the spell ends immediately. Failure The target takes full initial and persistent damage, and the target is sickened 1. If the target recovers from being sickened, the persistent damage ends and the spell ends. Critical Failure As failure, but the target is sickened 2.', heightened: 'Heightened (+1) The damage increases by 2d4 and the persistent damage by 1d4.', },
  { id: 'protection', name: 'Protection', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 351', range: 'touch', target: '1 willing creature', duration: '1 minute', traditions: ['divine', 'occult'], desc: 'You ward a creature against harm. The target gains a +1 status bonus to Armor Class and saving throws.', heightened: 'Heightened (3rd) You can choose to have the benefits also affect all your allies in a 10-foot emanation around the target.', },
  { id: 'protector-tree', name: 'Protector Tree', traits: ['Concentrate', 'Manipulate', 'Plant', 'Wood'], source: 'Player Core 2 pg. 249', range: '30 feet', duration: '1 minute', traditions: ['primal'], desc: 'A Medium tree suddenly grows in an unoccupied square within range. The tree has AC 10 and 10 Hit Points. Whenever an ally adjacent to the tree is hit by a Strike, the tree interposes its branches and takes the damage first. Any additional damage beyond what it takes to reduce the tree to 0 Hit Points is dealt to the original target. The tree isn\'t large enough to impede movement through its square. If the tree is in soil and survives to the end of the spell\'s duration, it remains as an ordinary, non-magical tree and continues to grow and thrive. The GM might determine that the tree disappears immediately in certain inhospitable situations.', heightened: 'Heightened (+1) The tree has an additional 10 Hit Points.', },
  { id: 'pummeling-rubble', name: 'Pummeling Rubble', traits: ['Concentrate', 'Earth', 'Manipulate'], source: 'Player Core pg. 351', area: '15-foot cone', defense: 'Reflex', traditions: ['arcane', 'primal'], desc: 'A spray of heavy rocks flies through the air in front of you. The rubble deals 2d4 bludgeoning damage to each creature in the area. Each creature must attempt a Reflex save. Critical Success The creature is unaffected. Success The creature takes half damage. Failure The creature takes full damage and is pushed 5 feet away from you. Critical Failure The creature takes double damage and is pushed 10 feet away from you.', heightened: 'Heightened (+1) The damage increases by 2d4.', },
  { id: 'purify-food-and-drink', name: 'Purify Food and Drink', traits: ['Necromancy'], source: 'Core Rulebook pg. 362', range: 'touch', target: '1 cubic foot of contaminated food or water', traditions: ['divine', 'primal'], desc: 'You remove toxins and contaminations from food and drink, making them safe to consume. This spell doesn\'t prevent future contamination, natural decay, or spoilage. One cubic foot of liquid is roughly 8 gallons.', },
  { id: 'ray-of-enfeeblement', name: 'Ray of Enfeeblement', traits: ['Attack', 'Necromancy'], source: 'Core Rulebook pg. 362', range: '30 feet', target: '1 creature', duration: '1 minute', defense: 'Fortitude', traditions: ['arcane', 'divine', 'occult'], desc: 'A ray with the power to sap a foe\'s strength flashes from your hand. Attempt a ranged spell attack against the target. If you succeed, that creature attempts a Fortitude save in order to determine the spell\'s effect. If you critically succeed on your attack roll, use the outcome for one degree of success worse than the result of its save. Critical Success The target is unaffected. Success The target becomes enfeebled 1. Failure The target becomes enfeebled 2. Critical Failure The target becomes enfeebled 3.', },
  { id: 'runic-body', name: 'Runic Body', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 354', range: 'touch', target: '1 willing creature', duration: '1 minute', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'Glowing runes appear on the target\'s body. All its unarmed attacks become +1 striking unarmed attacks, gaining a +1 item bonus to attack rolls and increasing the number of damage dice to two.', heightened: 'Heightened (6th) The unarmed attacks are +2 greater striking. Heightened (9th) The unarmed attacks are +3 major striking.', },
  { id: 'runic-weapon', name: 'Runic Weapon', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 354', range: 'touch', target: '1 weapon that is unattended or wielded by a willing creature', duration: '1 minute', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'The weapon glimmers with magic as temporary runes carve down its length. The target becomes a +1 striking weapon, gaining a +1 item bonus to attack rolls and increasing the number of weapon damage dice to two.', heightened: 'Heightened (6th) The weapon is +2 greater striking. Heightened (9th) The weapon is +3 major striking.', },
  { id: 'sanctuary', name: 'Sanctuary', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 355', range: 'touch', target: '1 creature', duration: '1 minute', traditions: ['divine', 'occult'], desc: 'You ward a creature with protective energy that deters attacks. Creatures attempting to attack the target must attempt a Will save each time. If the target uses a hostile action, the spell ends. Critical Success Sanctuary ends. Success The creature can attempt its attack and any other attacks against the target this turn. Failure The creature can\'t attack the target and wastes the action. It can\'t attempt further attacks against the target this turn. Critical Failure The creature wastes the action and can\'t attempt to attack the target for the rest of sanctuary\'s duration.', },
  { id: 'schadenfreude', name: 'Schadenfreude', traits: ['Concentrate', 'Emotion', 'Mental'], source: 'Player Core 2 pg. 250', range: '30 feet', target: 'the triggering foe', defense: 'Will', traditions: ['arcane', 'divine', 'occult'], cast: 'Reaction', desc: 'You distract your enemy with their feeling of smug pleasure when you fail catastrophically. It must attempt a Will save. Critical Success The creature is unaffected. Success The creature is distracted by its amusement and takes a –1 status penalty on Perception checks and Will saves for 1 round. Failure The creature is overcome by its amusement and is stupefied 1 for 1 round. Critical Failure The creature is lost in its amusement and is stupefied 2 for 1 round and stunned 1.', },
  { id: 'shillelagh', name: 'Shillelagh', traits: ['Plant', 'Transmutation'], source: 'Core Rulebook pg. 369', range: 'touch', target: '1 club or staff you hold', duration: '1 minute', traditions: ['primal'], desc: 'The target grows vines and leaves, brimming with primal energy. The target becomes a +1 striking weapon while in your hands, gaining a +1 item bonus to attack rolls and increasing the number of weapon damage dice to two. Additionally, as long as you are on your home plane, attacks you make with the target against aberrations, extraplanar creatures, and undead increase the number of weapon damage dice to three.', },
  { id: 'shocking-grasp', name: 'Shocking Grasp', traits: ['Attack', 'Electricity', 'Evocation'], source: 'Core Rulebook pg. 369', range: 'touch', target: '1 creature', traditions: ['arcane', 'primal'], desc: 'You shroud your hands in a crackling field of lightning. Make a melee spell attack roll. On a hit, the target takes 2d12 electricity damage. If the target is wearing metal armor or is made of metal, you gain a +1 circumstance bonus to your attack roll with shocking grasp, and the target also takes 1d4 persistent electricity damage on a hit. On a critical hit, double the initial damage, but not the persistent damage.', heightened: 'Heightened (+1) The damage increases by 1d12, and the persistent electricity damage increases by 1.', },
  { id: 'sleep', name: 'Sleep', traits: ['Concentrate', 'Incapacitation', 'Manipulate', 'Mental', 'Sleep'], source: 'Player Core pg. 357', range: '30 feet', area: '5-foot burst', defense: 'Will', traditions: ['arcane', 'occult'], desc: 'Each creature in the area becomes drowsy, possibly nodding off. A creature that falls unconscious from this spell doesn\'t fall prone or release what it\'s holding. This spell doesn\'t prevent creatures from waking up due to a successful Perception check, limiting its utility in combat. Critical Success The creature is unaffected. Success The creature takes a –1 status penalty to Perception checks for 1 round. Failure The creature falls unconscious. If it\'s still unconscious after 1 minute, it wakes up automatically. Critical Failure The creature falls unconscious. If it\'s still unconscious after 1 hour, it wakes up automatically.', heightened: 'Heightened (4th) The creatures fall unconscious for 1 round on a failure or 1 minute on a critical failure. They fall prone and release what they\'re holding, and they can\'t attempt Perception checks to wake up. When the duration ends, the creature is sleeping normally instead of automatically waking up.', },
  { id: 'soothe', name: 'Soothe', traits: ['Concentrate', 'Emotion', 'Healing', 'Manipulate', 'Mental'], source: 'Player Core pg. 357', range: '30 feet', target: '1 willing creature', duration: '1 minute', traditions: ['occult'], desc: 'You grace the target\'s mind, boosting its mental defenses and healing its wounds. The target regains 1d10+4 Hit Points when you Cast the Spell and gains a +2 status bonus to saves against mental effects for the duration.', heightened: 'Heightened (+1) The amount of healing increases by 1d10+4.', },
  { id: 'spider-sting', name: 'Spider Sting', traits: ['Concentrate', 'Manipulate', 'Poison'], source: 'Player Core pg. 358', range: 'touch', target: '1 creature', defense: 'Fortitude', traditions: ['arcane', 'primal'], desc: 'You magically duplicate a spider\'s venomous sting. You deal 1d4 piercing damage to the touched creature and afflict it with spider venom. The target must attempt a Fortitude save. Critical Success The target is unaffected. Success The target takes 1d4 poison damage. Failure The target is afflicted with spider venom at stage 1. Critical Failure The target is afflicted with spider venom at stage 2. Spider Venom (poison) Level 1; Maximum Duration 4 rounds; Stage 1 1d4 poison damage and enfeebled 1 (1 round); Stage 2 1d4 poison damage and enfeebled 2 (1 round)', },
  { id: 'spirit-link', name: 'Spirit Link', traits: ['Concentrate', 'Healing', 'Manipulate', 'Spirit'], source: 'Player Core pg. 358', range: '30 feet', target: '1 willing creature', duration: '10 minutes', traditions: ['divine', 'occult'], desc: 'You form a spiritual link with another creature, taking in its pain. When you Cast this Spell and at the start of each of your turns, if the target is below maximum Hit Points, it regains 2 Hit Points (or the difference between its current and maximum Hit Points, if that\'s lower). You lose as many Hit Points as the target regained. This is a spiritual transfer, so no effects apply that would increase the Hit Points the target regains or decrease the Hit Points you lose. This transfer also ignores any temporary Hit Points you or the target have. Since this effect doesn\'t involve vitality or void energy, spirit link works even if you or the target is undead. While the duration persists, you gain no benefit from regeneration or fast healing. You can Dismiss this spell, and if you\'re ever at 0 Hit Points, spirit link ends automatically.', heightened: 'Heightened (+1) The number of Hit Points transferred each time increases by 2.', },
  { id: 'summon-animal', name: 'Summon Animal', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core pg. 360', range: '30 feet', duration: 'sustained up to 1 minute', traditions: ['arcane', 'primal'], cast: 'Three Actions', desc: 'You summon a creature that has the animal trait and whose level is –1 to fight for you.', heightened: 'Heightened (2nd) Level 1. Heightened (3rd) Level 2. Heightened (4th) Level 3. Heightened (5th) Level 5. Heightened (6th) Level 7. Heightened (7th) Level 9. Heightened (8th) Level 11. Heightened (9th) Level 13. Heightened (10th) Level 15.', },
  { id: 'summon-construct', name: 'Summon Construct', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core pg. 360', range: '30 feet', duration: 'sustained up to 1 minute', traditions: ['arcane'], cast: 'Three Actions', desc: 'You summon a creature that has the construct trait and whose level is –1 to fight for you.', heightened: 'Heightened (2nd) Level 1. Heightened (3rd) Level 2. Heightened (4th) Level 3. Heightened (5th) Level 5. Heightened (6th) Level 7. Heightened (7th) Level 9. Heightened (8th) Level 11. Heightened (9th) Level 13. Heightened (10th) Level 15.', },
  { id: 'summon-fey', name: 'Summon Fey', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core pg. 360', range: '30 feet', duration: 'sustained up to 1 minute', traditions: ['occult', 'primal'], cast: 'Three Actions', desc: 'You summon a creature that has the fey trait and whose level is –1 to fight for you.', heightened: 'Heightened (2nd) Level 1. Heightened (3rd) Level 2. Heightened (4th) Level 3. Heightened (5th) Level 5. Heightened (6th) Level 7. Heightened (7th) Level 9. Heightened (8th) Level 11. Heightened (9th) Level 13. Heightened (10th) Level 15.', },
  { id: 'summon-lesser-servitor', name: 'Summon Lesser Servitor', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core 2 pg. 253', range: '30 feet', duration: 'sustained up to 1 minute', traditions: ['divine'], cast: 'Three Actions', desc: 'While deities jealously guard their most powerful servants from the summoning spells of those who aren\'t steeped in the faith, this spell allows you to conjure an inhabitant of the Outer Sphere with or without the deity\'s permission. You summon a common celestial, fiend, or monitor of level –1. You can choose to instead summon an animal of level –1 that hails from the Outer Sphere; you can choose for this animal to gain the celestial and holy traits, the fiend and unholy traits, or the monitor trait. It\'s anathema to summon a servitor if it has a holy or unholy trait that isn\'t allowed for your deity\'s sanctification.', heightened: 'Heightened (2nd) The creature can be level 1 or lower. Heightened (3rd) The creature can be level 2 or lower. Heightened (4th) The creature can be level 3 or lower.', },
  { id: 'summon-plant-or-fungus', name: 'Summon Plant or Fungus', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core pg. 361', range: '30 feet', duration: 'sustained up to 1 minute', traditions: ['primal'], cast: 'Three Actions', desc: 'You summon a creature that has the plant or fungus trait and whose level is –1 to fight for you.', heightened: 'Heightened (2nd) Level 1. Heightened (3rd) Level 2. Heightened (4th) Level 3. Heightened (5th) Level 5. Heightened (6th) Level 7. Heightened (7th) Level 9. Heightened (8th) Level 11. Heightened (9th) Level 13. Heightened (10th) Level 15.', },
  { id: 'summon-undead', name: 'Summon Undead', traits: ['Concentrate', 'Manipulate', 'Summon'], source: 'Player Core pg. 361', range: '30 feet', duration: 'sustained up to 1 minute', traditions: ['arcane', 'divine', 'occult'], cast: 'Three Actions', desc: 'You summon a creature that has the undead trait and whose level is –1 to fight for you.', heightened: 'Heightened (2nd) Level 1. Heightened (3rd) Level 2. Heightened (4th) Level 3. Heightened (5th) Level 5. Heightened (6th) Level 7. Heightened (7th) Level 9. Heightened (8th) Level 11. Heightened (9th) Level 13. Heightened (10th) Level 15.', },
  { id: 'sure-strike', name: 'Sure Strike', traits: ['Concentrate', 'Fortune'], source: 'Player Core pg. 361', duration: 'until the end of your turn', traditions: ['arcane', 'occult'], cast: 'Single Action', desc: 'The next time you make an attack roll before the end of your turn, roll it twice and use the better result. The attack ignores circumstance penalties to the attack roll and any flat check required due to the target being concealed or hidden. You are then temporarily immune to sure strike for 10 minutes.', },
  { id: 'tailwind', name: 'Tailwind', traits: ['Air', 'Concentrate', 'Manipulate'], source: 'Player Core pg. 362', duration: '1 hour', traditions: ['arcane', 'primal'], desc: 'The wind at your back pushes you to find new horizons. You gain a +10-foot status bonus to your Speed.', heightened: 'Heightened (2nd) The duration increases to 8 hours.', },
  { id: 'thoughtful-gift', name: 'Thoughtful Gift', traits: ['Manipulate', 'Teleportation'], source: 'Player Core 2 pg. 253', range: '120 feet', target: '1 willing creature', traditions: ['arcane', 'divine', 'occult'], cast: 'Single Action', desc: 'You teleport one object of light or negligible Bulk held in your hand to the target. The object appears instantly in the target\'s hand if they have a free hand, or at their feet if they don\'t. The target knows what object you\'re attempting to send them. If the target is unconscious or refuses to accept your gift, or if the spell would teleport a creature (even if the creature is inside an extradimensional container), the spell fails.', heightened: 'Heightened (3rd) The spell\'s range increases to 500 feet. Heightened (5th) As 3rd rank, and the object\'s maximum Bulk increases to 1. You can Cast the Spell with 3 actions instead of 1; doing so increases the range to 1 mile, and you don\'t need line of sight to the target, but you must be extremely familiar with the target.', },
  { id: 'thunderstrike', name: 'Thunderstrike', traits: ['Concentrate', 'Electricity', 'Manipulate', 'Sonic'], source: 'Player Core pg. 363', range: '120 feet', target: '1 creature', defense: 'basic Reflex', traditions: ['arcane', 'primal'], desc: 'You call down a tendril of lightning that cracks with thunder, dealing 1d12 electricity damage and 1d4 sonic damage to the target with a basic Reflex save. A target wearing metal armor or made of metal takes a –1 circumstance penalty to its save, and if damaged by the spell is clumsy 1 for 1 round.', heightened: 'Heightened (+1) The damage increases by 1d12 electricity and 1d4 sonic.', },
  { id: 'true-strike', name: 'True Strike', traits: ['Divination', 'Fortune'], source: 'Core Rulebook pg. 379', duration: 'until the end of your turn', traditions: ['arcane', 'occult'], cast: 'Single Action', desc: 'A glimpse into the future ensures your next blow strikes true. The next time you make an attack roll before the end of your turn, roll the attack twice and use the better result. The attack ignores circumstance penalties to the attack roll and any flat check required due to the target being concealed or hidden.', },
  { id: 'unseen-servant', name: 'Unseen Servant', traits: ['Conjuration'], source: 'Core Rulebook pg. 380', range: '60 feet', duration: 'sustained', traditions: ['arcane', 'occult'], cast: 'Three Actions', desc: 'You summon an unseen servant, which you can command as part of Sustaining the Spell. It serves you until its Hit Points are reduced to 0, at which point the spell ends, or until you stop Sustaining the Spell. The unseen servant gains the summoned trait.', },
  { id: 'vanishing-tracks', name: 'Vanishing Tracks', traits: ['Concentrate', 'Manipulate'], source: 'Player Core pg. 365', duration: '1 hour', traditions: ['primal'], desc: 'You obscure the tracks you leave behind. The DC of checks to Track you gains a +4 status bonus or is equal to your spell DC, whichever results in a higher DC.', heightened: 'Heightened (2nd) The duration increases to 8 hours. Heightened (4th) The duration increases to 8 hours. The spell has a range of 20 feet and targets up to 10 creatures.', },
  { id: 'ventriloquism', name: 'Ventriloquism', traits: ['Auditory', 'Concentrate', 'Illusion', 'Manipulate'], source: 'Player Core pg. 366', duration: '10 minutes', traditions: ['arcane', 'divine', 'occult', 'primal'], desc: 'Whenever you speak or make any other sound vocally, you can make your vocalization seem to originate from somewhere else within 60 feet, and you can change that apparent location freely as you vocalize. Any creature that hears the sound can attempt to disbelieve your illusion.', heightened: 'Heightened (2nd) The spell\'s duration increases to 1 hour, and you can also change the tone, quality, and other aspects of your voice. Before a creature can attempt to disbelieve your illusion, it must actively attempt a Perception check or otherwise use actions to interact with the sound.', },
];

export function getSpellsForTradition(list, traditionCode, classId) {
  return list.filter((s) => s.traditions.includes(traditionCode) && (!s.classId || s.classId === classId) && !s.patronId);
}

// The one hex cantrip a Witch's chosen Patron grants automatically (see the
// CANTRIPS comment above the Witch hex entries) — looked up directly by
// patronId rather than through getSpellsForTradition, since it's never a
// free pick from the general pool.
export function getPatronHex(patronId) {
  return CANTRIPS.find((s) => s.patronId === patronId);
}

export const TRADITION_LABELS = {
  arcane: 'Arcane',
  divine: 'Divine',
  occult: 'Occult',
  primal: 'Primal',
};
